return {
    -- InnerPowerNpc [18786]
    ["STR_ID_InnerPowerNpc[18786][Text1]"] = "To concentrate on the study of humankind`s potential, I completely",
    ["STR_ID_InnerPowerNpc[18786][Text2]"] = "Good to see you again. If you've finished the studying the Inner Power Book I gave",
    ["STR_ID_InnerPowerNpc[18786][Text3]"] = "Kid, you`re not strong enough to study my Inner Power Books. The unusual power may hurt you instead.",
    ["STR_ID_InnerPowerNpc[18786][Text4]"] = "@STR_COMMON[14]",
    -- {0}=DbItem.Name
    ["STR_ID_InnerPowerNpc[18786][Text5]"] = "@STR_COMMON[668]",
    -- {0}=DbItem.Name
    ["STR_ID_InnerPowerNpc[18786][Text6]"] = "@STR_COMMON[669]",
    ["STR_ID_InnerPowerNpc[18786][Text7]"] = "You've completed the inner power concept .",
    ["STR_ID_InnerPowerNpc[18786][Text8]"] = "@STR_COMMON[14]",
    -- {0}=DbItem.Name
    ["STR_ID_InnerPowerNpc[18786][Text9]"] = "@STR_COMMON[668]",
    -- {0}=DbItem.Name
    ["STR_ID_InnerPowerNpc[18786][Text10]"] = "@STR_COMMON[669]",
    -- {0}=DbItem.Name
    ["STR_ID_InnerPowerNpc[18786][Text11]"] = "@STR_COMMON[668]",
    ["STR_ID_InnerPowerNpc[18786][Text12]"] = "During the 100 years, I created numerous concepts, but found it too complicated. Therefore, I embodies these concepts through books.",
    ["STR_ID_InnerPowerNpc[18786][Text13]"] = "Meeting you was fate. I`d like present you a Universal Concept (A). When you acquire its essence and reach the perfect level, you can",
    ["STR_ID_InnerPowerNpc[18786][Text14]"] = "@STR_COMMON[119]",
    ["STR_ID_InnerPowerNpc[18786][Text15]"] = "@STR_COMMON[119]",
    ["STR_ID_InnerPowerNpc[18786][Text16]"] = "@STR_COMMON[119]",
    ["STR_ID_InnerPowerNpc[18786][Text17]"] = "@STR_COMMON[120]",
    ["STR_ID_InnerPowerNpc[18786][Text18]"] = "@STR_COMMON[119]",
    ["STR_ID_InnerPowerNpc[18786][Text19]"] = "You said you came from Twin City and were looking for Thief Chen? What`s the problem?",
    ["STR_ID_InnerPowerNpc[18786][Text20]"] = "Well, I`m still going to need you to prove yourself. Go kill 5 Bandits, first!",
    ["STR_ID_InnerPowerNpc[18786][Text21]"] = "Fine. I guess I can trust you, after all.",
    ["STR_ID_InnerPowerNpc[18786][Text22]"] = "@STR_COMMON[120]",
    ["STR_ID_InnerPowerNpc[18786][Text23]"] = "Why are you still here? Deliver the letter to Wong, right away!",
    ["STR_ID_InnerPowerNpc[18786][Text24]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text25]"] = "Hey, friend! Check your bag. The letter is right there!",
    ["STR_ID_InnerPowerNpc[18786][Text26]"] = "@STR_COMMON[113]",
    ["STR_ID_InnerPowerNpc[18786][Text27]"] = "@STR_COMMON[113]",
    ["STR_ID_InnerPowerNpc[18786][Text28]"] = "@STR_COMMON[113]",
    ["STR_ID_InnerPowerNpc[18786][Text29]"] = "@STR_COMMON[113]",
    ["STR_ID_InnerPowerNpc[18786][Text30]"] = "@STR_COMMON[113]",
    ["STR_ID_InnerPowerNpc[18786][Text31]"] = "@STR_COMMON[114]",
    ["STR_ID_InnerPowerNpc[18786][Text32]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text33]"] = "@STR_COMMON[114]",
    ["STR_ID_InnerPowerNpc[18786][Text34]"] = "The problem is, I was wounded by the guards as I escaped. Can you take a message to my connector, Thief Chen?",
    ["STR_ID_InnerPowerNpc[18786][Text35]"] = "Thank you for the letter!",
    ["STR_ID_InnerPowerNpc[18786][Text36]"] = "Here`s your reward. Thank you again!",
    ["STR_ID_InnerPowerNpc[18786][Text37]"] = "@STR_COMMON[141]",
    ["STR_ID_InnerPowerNpc[18786][Text38]"] = "@STR_COMMON[141]",
    ["STR_ID_InnerPowerNpc[18786][Text39]"] = "@STR_COMMON[141]",
    ["STR_ID_InnerPowerNpc[18786][Text40]"] = "I usually charge a fortune for this work, but as you`re going to rid us of Cloud the Lustful... I suppose I can make an exception.",
    ["STR_ID_InnerPowerNpc[18786][Text41]"] = "@STR_COMMON[131]",
    ["STR_ID_InnerPowerNpc[18786][Text42]"] = "@STR_COMMON[131]",
    ["STR_ID_InnerPowerNpc[18786][Text43]"] = "@STR_COMMON[131]",
    ["STR_ID_InnerPowerNpc[18786][Text44]"] = "@STR_COMMON[131]",
    ["STR_ID_InnerPowerNpc[18786][Text45]"] = "@STR_COMMON[131]",
    ["STR_ID_InnerPowerNpc[18786][Text46]"] = "@STR_COMMON[131]",
    ["STR_ID_InnerPowerNpc[18786][Text47]"] = "Yes! I`m in trouble now, and I could use your help. Someone has stolen my Spun Gold Armor. Were this found out by the Emperor,",
    ["STR_ID_InnerPowerNpc[18786][Text48]"] = "Yes! I guess it was those bandits who stole my armor. You should find them and try to recover any clues you can. Feel free to use force.",
    ["STR_ID_InnerPowerNpc[18786][Text49]"] = "Rumor has it that those bandits who roam outside the city have something to do with this. Go find them and see what they know!",
    ["STR_ID_InnerPowerNpc[18786][Text50]"] = "This is an invitation to the Treasure Appraisal Meeting. Now I`m positive the Spun Gold Armor was stolen by Cloud the Lustful!",
    ["STR_ID_InnerPowerNpc[18786][Text51]"] = "@STR_COMMON[131]",
    ["STR_ID_InnerPowerNpc[18786][Text52]"] = "Cloud the Lustful is the head of those bandits. They are a motley crew... Notorious and capable of committing",
    ["STR_ID_InnerPowerNpc[18786][Text53]"] = "Thank you! I thought I would never regain my precious armor. Please, let me repay you for your heroic feat.",
    ["STR_ID_InnerPowerNpc[18786][Text54]"] = "He usually shows up around a small altar in the southwest of Phoenix Castle. He is a randy old man, and actually quite disgusting.",
    ["STR_ID_InnerPowerNpc[18786][Text55]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text56]"] = "Are you kidding me? You`ve already got the offering!",
    ["STR_ID_InnerPowerNpc[18786][Text57]"] = "Thank you for retrieving my Spun Gold Armor. Now you can speak with Taskmaster Chang, to claim your reward.",
    ["STR_ID_InnerPowerNpc[18786][Text58]"] = "@STR_COMMON[156]",
    ["STR_ID_InnerPowerNpc[18786][Text59]"] = "@STR_COMMON[156]",
    ["STR_ID_InnerPowerNpc[18786][Text60]"] = "@STR_COMMON[156]",
    ["STR_ID_InnerPowerNpc[18786][Text61]"] = "@STR_COMMON[156]",
    ["STR_ID_InnerPowerNpc[18786][Text62]"] = "@STR_COMMON[156]",
    ["STR_ID_InnerPowerNpc[18786][Text63]"] = "@STR_COMMON[156]",
    ["STR_ID_InnerPowerNpc[18786][Text64]"] = "Hats off to your valor! You saved my life! Please accept this, with my thanks.",
    ["STR_ID_InnerPowerNpc[18786][Text65]"] = "Thank you! You saved me! Now go claim your reward from Taskmaster Chang!",
    ["STR_ID_InnerPowerNpc[18786][Text66]"] = "Yes. But sigh... I still haven`t gotten over it...",
    ["STR_ID_InnerPowerNpc[18786][Text67]"] = "Thank you. I heard there is a rat called the Fire Rat L38 outside the castle... Its eye and meat could be used to make a powerful",
    ["STR_ID_InnerPowerNpc[18786][Text68]"] = "Well, you are so generous... thank you. The recipe for the Azure Pill belongs to Pharmacist Mu Mu (182,241). Please go there",
    ["STR_ID_InnerPowerNpc[18786][Text69]"] = "@STR_COMMON[169]",
    ["STR_ID_InnerPowerNpc[18786][Text70]"] = "@STR_COMMON[169]",
    ["STR_ID_InnerPowerNpc[18786][Text71]"] = "@STR_COMMON[169]",
    ["STR_ID_InnerPowerNpc[18786][Text72]"] = "Yes, sure. So my old friend Mu Mu sent you here? Let me see... you need to collect 1 Ratling Eye and 3 Ratling Meat, yourself,",
    ["STR_ID_InnerPowerNpc[18786][Text73]"] = "@STR_COMMON[26]",
    ["STR_ID_InnerPowerNpc[18786][Text74]"] = "@STR_COMMON[161]",
    ["STR_ID_InnerPowerNpc[18786][Text75]"] = "@STR_COMMON[161]",
    ["STR_ID_InnerPowerNpc[18786][Text76]"] = "@STR_COMMON[161]",
    ["STR_ID_InnerPowerNpc[18786][Text77]"] = "@STR_COMMON[162]",
    ["STR_ID_InnerPowerNpc[18786][Text78]"] = "@STR_COMMON[163]",
    ["STR_ID_InnerPowerNpc[18786][Text79]"] = "@STR_COMMON[161]",
    ["STR_ID_InnerPowerNpc[18786][Text80]"] = "@STR_COMMON[161]",
    ["STR_ID_InnerPowerNpc[18786][Text81]"] = "@STR_COMMON[161]",
    ["STR_ID_InnerPowerNpc[18786][Text82]"] = "@STR_COMMON[161]",
    ["STR_ID_InnerPowerNpc[18786][Text83]"] = "@STR_COMMON[164]",
    ["STR_ID_InnerPowerNpc[18786][Text84]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text85]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text86]"] = "Haha, the Azure Pill is done!",
    ["STR_ID_InnerPowerNpc[18786][Text87]"] = "@STR_COMMON[164]",
    ["STR_ID_InnerPowerNpc[18786][Text88]"] = "Don`t bother me, right now. Get some manners and be patient, OK?",
    ["STR_ID_InnerPowerNpc[18786][Text89]"] = "Oh, Scholar Wu`s disease... It`s difficult to cure. I`ll try my best, but I`ll need your help gathering things I need.",
    ["STR_ID_InnerPowerNpc[18786][Text90]"] = "@STR_COMMON[162]",
    ["STR_ID_InnerPowerNpc[18786][Text91]"] = "Excellent! All of the ingredients are here. Now leave me alone for a while so I can combine them into an Azure Pill.",
    ["STR_ID_InnerPowerNpc[18786][Text92]"] = "Now, bring me 1 Ratling Eye and 3 Ratling Meat. Make sure to get the 2 Herb Packs from Bian Qing (342,232).",
    ["STR_ID_InnerPowerNpc[18786][Text93]"] = "@STR_COMMON[163]",
    ["STR_ID_InnerPowerNpc[18786][Text94]"] = "Ever wonder who makes the best arrows in the world? It`s my dad!",
    ["STR_ID_InnerPowerNpc[18786][Text95]"] = "@STR_COMMON[142]",
    ["STR_ID_InnerPowerNpc[18786][Text96]"] = "@STR_COMMON[143]",
    ["STR_ID_InnerPowerNpc[18786][Text97]"] = "@STR_COMMON[142]",
    ["STR_ID_InnerPowerNpc[18786][Text98]"] = "@STR_COMMON[143]",
    ["STR_ID_InnerPowerNpc[18786][Text99]"] = "He should be near the river between the Peach Blossom Garden and Wind Plain. There are many birds roaming around.",
    ["STR_ID_InnerPowerNpc[18786][Text100]"] = "@STR_COMMON[146]",
    ["STR_ID_InnerPowerNpc[18786][Text101]"] = "@STR_COMMON[146]",
    ["STR_ID_InnerPowerNpc[18786][Text102]"] = "@STR_COMMON[146]",
    ["STR_ID_InnerPowerNpc[18786][Text103]"] = "@STR_COMMON[146]",
    ["STR_ID_InnerPowerNpc[18786][Text104]"] = "@STR_COMMON[146]",
    ["STR_ID_InnerPowerNpc[18786][Text105]"] = "@STR_COMMON[146]",
    ["STR_ID_InnerPowerNpc[18786][Text106]"] = "@STR_COMMON[147]",
    ["STR_ID_InnerPowerNpc[18786][Text107]"] = "@STR_COMMON[146]",
    ["STR_ID_InnerPowerNpc[18786][Text108]"] = "Oh, my son is looking for me? Alright, I`ll be able to head home as soon as I can gather enough feathers.",
    ["STR_ID_InnerPowerNpc[18786][Text109]"] = "That`s very kind of you! Thank you!",
    ["STR_ID_InnerPowerNpc[18786][Text110]"] = "Ouch...my foot! I accidentally sprained my ankle while I was trapping a gigantic bird, so it`s hard for",
    ["STR_ID_InnerPowerNpc[18786][Text111]"] = "Thank you for helping me! Take this as your reward. You deserve it.",
    ["STR_ID_InnerPowerNpc[18786][Text112]"] = "The Vultures are nesting in the Love Canyon, but be careful! They`re very dangerous.",
    ["STR_ID_InnerPowerNpc[18786][Text113]"] = "One last thing... I`ve been dreaming of getting my hands on some of the native vulture`s feathers.",
    ["STR_ID_InnerPowerNpc[18786][Text114]"] = "Thank you for what you`ve done for me! Please pay a visit to Taskmaster Chang and claim your reward.",
    ["STR_ID_InnerPowerNpc[18786][Text115]"] = "Thank you for helping me. Now you can go pick a reward from Taskmaster Chang.",
    ["STR_ID_InnerPowerNpc[18786][Text116]"] = "You certainly deserve your good reputation! I heard the strange birds from the Love Canyon can cast magic spells",
    ["STR_ID_InnerPowerNpc[18786][Text117]"] = "@STR_COMMON[147]",
    ["STR_ID_InnerPowerNpc[18786][Text118]"] = "Thank you very much for collecting the Robin Feathers for me! I can make good arrows with it!",
    ["STR_ID_InnerPowerNpc[18786][Text119]"] = "Hey, I don`t see any feathers on you. Don`t cheat me!",
    ["STR_ID_InnerPowerNpc[18786][Text120]"] = " Hi! I`m the fletcher of Twin City. It`s my job to make exquisite arrows. Now, I`m out of the material I need to make arrows. Can you",
    ["STR_ID_InnerPowerNpc[18786][Text121]"] = "@STR_COMMON[186]",
    ["STR_ID_InnerPowerNpc[18786][Text122]"] = "@STR_COMMON[186]",
    ["STR_ID_InnerPowerNpc[18786][Text123]"] = "Thank you for your help. This means a lot to me, since I`ll finally be able to go home and get a break!",
    ["STR_ID_InnerPowerNpc[18786][Text124]"] = "@STR_COMMON[185]",
    ["STR_ID_InnerPowerNpc[18786][Text125]"] = "@STR_COMMON[185]",
    ["STR_ID_InnerPowerNpc[18786][Text126]"] = "@STR_COMMON[185]",
    ["STR_ID_InnerPowerNpc[18786][Text127]"] = "@STR_COMMON[185]",
    ["STR_ID_InnerPowerNpc[18786][Text128]"] = "@STR_COMMON[185]",
    ["STR_ID_InnerPowerNpc[18786][Text129]"] = "@STR_COMMON[185]",
    ["STR_ID_InnerPowerNpc[18786][Text130]"] = "Yes! Nice to see you! I love collecting antiques. They`ve been my biggest passion in life.",
    ["STR_ID_InnerPowerNpc[18786][Text131]"] = "Oh, I could have helped you... But... you know... the Antique Ring... that`s valuable...",
    ["STR_ID_InnerPowerNpc[18786][Text132]"] = "Thank you. I`ll get them to take their medicine, now.",
    ["STR_ID_InnerPowerNpc[18786][Text133]"] = "You`re smart. To be honest with you, I could use some help. I need 12 Stanchers and 12 Agrypnotics to help with my family`s illness.",
    ["STR_ID_InnerPowerNpc[18786][Text134]"] = "Thank you for what you`ve done for the village. I won`t soon forget your heroism!",
    ["STR_ID_InnerPowerNpc[18786][Text135]"] = "How come you didn`t kill enough Ratlings?",
    ["STR_ID_InnerPowerNpc[18786][Text136]"] = "Oh, thank you ,thank you... but... Will you please kill 20 Ratlings, too? They are really quite annoying, nibbling our food all the time.",
    ["STR_ID_InnerPowerNpc[18786][Text137]"] = "My son is back! How can I thank you enough!",
    ["STR_ID_InnerPowerNpc[18786][Text138]"] = "Have you heard the news? Recently, many people were robbed by the Bandits who hide in Maple Forest.",
    ["STR_ID_InnerPowerNpc[18786][Text139]"] = "Can you please head into Maple Forest and deliver this Castle Gate Scroll to my son?",
    ["STR_ID_InnerPowerNpc[18786][Text140]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text141]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text142]"] = "You have the Scroll. Hurry up and deliver it to my son.",
    ["STR_ID_InnerPowerNpc[18786][Text143]"] = "With my family finally together and safe, the ring is not important to me, anymore. Please, accept it as your reward.",
    ["STR_ID_InnerPowerNpc[18786][Text144]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text145]"] = "@STR_COMMON[183]",
    ["STR_ID_InnerPowerNpc[18786][Text146]"] = "@STR_COMMON[183]",
    ["STR_ID_InnerPowerNpc[18786][Text147]"] = "@STR_COMMON[183]",
    ["STR_ID_InnerPowerNpc[18786][Text148]"] = "@STR_COMMON[183]",
    ["STR_ID_InnerPowerNpc[18786][Text149]"] = "@STR_COMMON[183]",
    ["STR_ID_InnerPowerNpc[18786][Text150]"] = "I heard Antique Dealer Shen has an Antique Ring which could be converted into Mystic Ring. But seems that I can`t even see it...",
    ["STR_ID_InnerPowerNpc[18786][Text151]"] = "A little bird told me an antique dealer named Shen (779,477) is living in a village near Phoenix Castle, and has an Antique Ring. His",
    ["STR_ID_InnerPowerNpc[18786][Text152]"] = "Oh gosh, the Mystic Ring... it`s no different than an ordinary one. But you truly did a great thing.",
    ["STR_ID_InnerPowerNpc[18786][Text153]"] = "Please use the AntiqueRing.",
    ["STR_ID_InnerPowerNpc[18786][Text154]"] = "Finally, the Mystic Ring! Hats off to your gallantry and valor! Now, will you",
    ["STR_ID_InnerPowerNpc[18786][Text155]"] = "Finally, the Mystic Ring! I can`t wait to see its magic! Please, wear it and show me its power! Right now!",
    ["STR_ID_InnerPowerNpc[18786][Text156]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text157]"] = "Thank you for what you`ve done for me! Now you can report to Taskmaster Chang and claim your reward.",
    ["STR_ID_InnerPowerNpc[18786][Text158]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text159]"] = "You have the ring.",
    ["STR_ID_InnerPowerNpc[18786][Text160]"] = "@STR_COMMON[172]",
    ["STR_ID_InnerPowerNpc[18786][Text161]"] = "@STR_COMMON[172]",
    ["STR_ID_InnerPowerNpc[18786][Text162]"] = "@STR_COMMON[172]",
    ["STR_ID_InnerPowerNpc[18786][Text163]"] = "@STR_COMMON[172]",
    ["STR_ID_InnerPowerNpc[18786][Text164]"] = "What? Monkeys are attacking people! I`ve never heard that before!",
    ["STR_ID_InnerPowerNpc[18786][Text165]"] = "Are you sure it`s monkey`s heart? As far as I know, it`s posioned!",
    ["STR_ID_InnerPowerNpc[18786][Text166]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text167]"] = "You did go shockingly frantic! Well, your syndrome reminded me of the bites by Venomous Apes.",
    ["STR_ID_InnerPowerNpc[18786][Text168]"] = "Look at this poison...I need someone to test it...",
    ["STR_ID_InnerPowerNpc[18786][Text169]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text170]"] = "Hey! You still have the poison!",
    ["STR_ID_InnerPowerNpc[18786][Text171]"] = "The Venomous Apes are harassing people in Love Canyon (795,471) on the outskirts of Ape City.",
    ["STR_ID_InnerPowerNpc[18786][Text172]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text173]"] = "Venomous Apes live in Love Canyon (795,471). People will turn frantic after being bitten by them. Search there for clues.",
    ["STR_ID_InnerPowerNpc[18786][Text174]"] = "@STR_COMMON[171]",
    ["STR_ID_InnerPowerNpc[18786][Text175]"] = "@STR_COMMON[171]",
    ["STR_ID_InnerPowerNpc[18786][Text176]"] = "@STR_COMMON[171]",
    ["STR_ID_InnerPowerNpc[18786][Text177]"] = "@STR_COMMON[171]",
    ["STR_ID_InnerPowerNpc[18786][Text178]"] = "@STR_COMMON[171]",
    ["STR_ID_InnerPowerNpc[18786][Text179]"] = "@STR_COMMON[171]",
    ["STR_ID_InnerPowerNpc[18786][Text180]"] = "It`s weird that the monkeys outside the city strangely went frantic and began to attack villagers...",
    ["STR_ID_InnerPowerNpc[18786][Text181]"] = "Yes. You may have noticed those monkeys outside our city. They used to be benign, though sometimes a little bit naughty.",
    ["STR_ID_InnerPowerNpc[18786][Text182]"] = "Thank you for what you`ve done for the people!",
    ["STR_ID_InnerPowerNpc[18786][Text183]"] = "Only a genuine brave heart can conquer all. Please go and find out what`s driving the monkeys berserk. Quick!",
    ["STR_ID_InnerPowerNpc[18786][Text184]"] = "Dear me! What a horrible heart! It`s decayed. I`ve never seen this kind of thing before. Will you go visit Royal Doctor Li",
    ["STR_ID_InnerPowerNpc[18786][Text185]"] = "You got the Devilish Sword! I`m really impressed. This is your reward.",
    ["STR_ID_InnerPowerNpc[18786][Text186]"] = "Thank you for restoring peace to our city. Now you can go claim your reward from Taskmaster Chang.",
    ["STR_ID_InnerPowerNpc[18786][Text187]"] = "@STR_COMMON[173]",
    ["STR_ID_InnerPowerNpc[18786][Text188]"] = "@STR_COMMON[173]",
    ["STR_ID_InnerPowerNpc[18786][Text189]"] = "@STR_COMMON[173]",
    ["STR_ID_InnerPowerNpc[18786][Text190]"] = "@STR_COMMON[173]",
    ["STR_ID_InnerPowerNpc[18786][Text191]"] = "@STR_COMMON[173]",
    ["STR_ID_InnerPowerNpc[18786][Text192]"] = "@STR_COMMON[173]",
    ["STR_ID_InnerPowerNpc[18786][Text193]"] = "@STR_COMMON[173]",
    ["STR_ID_InnerPowerNpc[18786][Text194]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text195]"] = "You`ve got the Paper Figure. Hurry to find General Zhao!",
    ["STR_ID_InnerPowerNpc[18786][Text196]"] = "Haha! Thank you for allowing me to control you like a pawn! I could not have taken my revenge without you. General Zhao",
    ["STR_ID_InnerPowerNpc[18786][Text197]"] = "@STR_COMMON[174]",
    ["STR_ID_InnerPowerNpc[18786][Text198]"] = "Find General Zhao (262,247) in Twin City. We used to be best friends. But we had a big fight over some rift",
    ["STR_ID_InnerPowerNpc[18786][Text199]"] = "Oh, my, General Zhao`s Hair... This really reminds me of those days... when we were fighting side by side...",
    ["STR_ID_InnerPowerNpc[18786][Text200]"] = "Pity! I can`t go visit General Zhao (262,247) myself. I do hope everything is fine with him. Will you please bring me",
    ["STR_ID_InnerPowerNpc[18786][Text201]"] = "@STR_COMMON[174]",
    ["STR_ID_InnerPowerNpc[18786][Text202]"] = "@STR_COMMON[175]",
    ["STR_ID_InnerPowerNpc[18786][Text203]"] = "@STR_COMMON[175]",
    ["STR_ID_InnerPowerNpc[18786][Text204]"] = "I didn`t expect you would return so soon. This is your reward. Please accept it.",
    ["STR_ID_InnerPowerNpc[18786][Text205]"] = "Hey you, one Silk Pack is enough.",
    ["STR_ID_InnerPowerNpc[18786][Text206]"] = "@STR_COMMON[176]",
    ["STR_ID_InnerPowerNpc[18786][Text207]"] = "Only the Painter Feng Kang (556,571) in Ape City can paint the best portrait. No more waste of time, please.",
    ["STR_ID_InnerPowerNpc[18786][Text208]"] = "Ahhh, excellent. You have done well, and I commend you. But, if it`s not too much too ask, I still have one more wish. Will",
    ["STR_ID_InnerPowerNpc[18786][Text209]"] = "@STR_COMMON[176]",
    ["STR_ID_InnerPowerNpc[18786][Text210]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text211]"] = "@STR_COMMON[180]",
    ["STR_ID_InnerPowerNpc[18786][Text212]"] = "@STR_COMMON[180]",
    ["STR_ID_InnerPowerNpc[18786][Text213]"] = "@STR_COMMON[180]",
    ["STR_ID_InnerPowerNpc[18786][Text214]"] = "Wake up! Don`t you realize now? The hair, the silk pack, and the portait...they are all for an enchantment! General Zhao has been",
    ["STR_ID_InnerPowerNpc[18786][Text215]"] = "@STR_COMMON[179]",
    ["STR_ID_InnerPowerNpc[18786][Text216]"] = "@STR_COMMON[179]",
    ["STR_ID_InnerPowerNpc[18786][Text217]"] = "Why not send the Portrait to General Amber right now? What`s been dragging you?",
    ["STR_ID_InnerPowerNpc[18786][Text218]"] = "The revenant of General Amber has sent you here for a Portrait of General Zhao? Ok, I will try my best... But this sure",
    ["STR_ID_InnerPowerNpc[18786][Text219]"] = "@STR_COMMON[177]",
    ["STR_ID_InnerPowerNpc[18786][Text220]"] = "@STR_COMMON[177]",
    ["STR_ID_InnerPowerNpc[18786][Text221]"] = "@STR_COMMON[178]",
    ["STR_ID_InnerPowerNpc[18786][Text222]"] = "@STR_COMMON[177]",
    ["STR_ID_InnerPowerNpc[18786][Text223]"] = "@STR_COMMON[178]",
    ["STR_ID_InnerPowerNpc[18786][Text224]"] = "@STR_COMMON[178]",
    ["STR_ID_InnerPowerNpc[18786][Text225]"] = "@STR_COMMON[178]",
    ["STR_ID_InnerPowerNpc[18786][Text226]"] = "What`s wrong with me? It seemed I`ve had a lot of Conquer7110s these days... I see, it`s a spell... an enchantment... You",
    ["STR_ID_InnerPowerNpc[18786][Text227]"] = "Thank you, for saving my life! You can go claim your reward from Taskmaster Chang!",
    ["STR_ID_InnerPowerNpc[18786][Text228]"] = "Didn`t I just give you my Hair?",
    ["STR_ID_InnerPowerNpc[18786][Text229]"] = "Oh... General Amber missed me... I`m surprised... He always hated me so much. What would make him change his mind?",
    ["STR_ID_InnerPowerNpc[18786][Text230]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text231]"] = "@STR_COMMON[178]",
    ["STR_ID_InnerPowerNpc[18786][Text232]"] = "You can`t just venture out alone in this cruel world, the team system will help you to find some companions to help you! There are two methods to help you to find companions. The first one is to click team button to create a team by yourself and invite",
    ["STR_ID_InnerPowerNpc[18786][Text233]"] = "The second method is to click team button and click join to apply to join a team. You can join the team if there are less than 5 members in it, after the team leader agrees.",
    ["STR_ID_InnerPowerNpc[18786][Text234]"] = "You will receive bonus experience when slaying monsters in a team. If there is a new player in the team, the team leader will receive Virtue Points when that player levels up. Furthermore, some special quests require players to join as a team.",
    ["STR_ID_InnerPowerNpc[18786][Text235]"] = "There are many things for you to learn in this world! Um, I guess you want to learn more, huh? Let me see. What about equipment and armors? That will be useful! Now speak with the Armor in Twin City, he will tell you something about the armors.",
    ["STR_ID_InnerPowerNpc[18786][Text236]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text237]"] = "@STR_COMMON[155]",
    ["STR_ID_InnerPowerNpc[18786][Text238]"] = "@STR_COMMON[155]",
    ["STR_ID_InnerPowerNpc[18786][Text239]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text240]"] = "@STR_COMMON[154]",
    ["STR_ID_InnerPowerNpc[18786][Text241]"] = "@STR_COMMON[154]",
    ["STR_ID_InnerPowerNpc[18786][Text242]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text243]"] = "@STR_COMMON[153]",
    ["STR_ID_InnerPowerNpc[18786][Text244]"] = "@STR_COMMON[153]",
    ["STR_ID_InnerPowerNpc[18786][Text245]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text246]"] = "@STR_COMMON[152]",
    ["STR_ID_InnerPowerNpc[18786][Text247]"] = "The rock has an green halo around it.",
    ["STR_ID_InnerPowerNpc[18786][Text248]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text249]"] = "@STR_COMMON[152]",
    ["STR_ID_InnerPowerNpc[18786][Text250]"] = "The rock has an red yellow around it.",
    ["STR_ID_InnerPowerNpc[18786][Text251]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text252]"] = "The rock has an orange halo around it.",
    ["STR_ID_InnerPowerNpc[18786][Text253]"] = "The rock has an red orange around it.",
    ["STR_ID_InnerPowerNpc[18786][Text254]"] = "@STR_COMMON[150]",
    ["STR_ID_InnerPowerNpc[18786][Text255]"] = "@STR_COMMON[150]",
    ["STR_ID_InnerPowerNpc[18786][Text256]"] = "@STR_COMMON[150]",
    ["STR_ID_InnerPowerNpc[18786][Text257]"] = "Snake Men? Yes, I`ve heard of it. People get lunatic after being bitten by them. It may have been because of their",
    ["STR_ID_InnerPowerNpc[18786][Text258]"] = "@STR_COMMON[3]",
    ["STR_ID_InnerPowerNpc[18786][Text259]"] = "Herbs have a variety of uses, including culinary, medicinal, or in some cases even spiritual meditation.",
    ["STR_ID_InnerPowerNpc[18786][Text260]"] = "Now we need Rainbow Powder to relieve Du San`s syndrome. It`s made of powder of seven different colors.",
    ["STR_ID_InnerPowerNpc[18786][Text261]"] = "@STR_COMMON[3]",
    ["STR_ID_InnerPowerNpc[18786][Text262]"] = "No more delays. Take the toxins now. Pick up two of them and right click to use. If your choice is right, you will arrive in Kun Lun and",
    ["STR_ID_InnerPowerNpc[18786][Text263]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text264]"] = "@STR_COMMON[151]",
    ["STR_ID_InnerPowerNpc[18786][Text265]"] = "@STR_COMMON[151]",
    ["STR_ID_InnerPowerNpc[18786][Text266]"] = "@STR_COMMON[58]",
    ["STR_ID_InnerPowerNpc[18786][Text267]"] = "@STR_COMMON[58]",
    ["STR_ID_InnerPowerNpc[18786][Text268]"] = "@STR_COMMON[58]",
    ["STR_ID_InnerPowerNpc[18786][Text269]"] = "@STR_COMMON[58]",
    ["STR_ID_InnerPowerNpc[18786][Text270]"] = "The Emperor keeps track of all those who make donations to his empire. When you have reached level 70, you are able to donate",
    ["STR_ID_InnerPowerNpc[18786][Text271]"] = "~money to the Emperor for your nobility rank, which can increase your battle power. Your title is determined by the amount of",
    ["STR_ID_InnerPowerNpc[18786][Text272]"] = "~money you have donated.",
    ["STR_ID_InnerPowerNpc[18786][Text273]"] = "Click the Nobility Button, input the amount of money you want to donate in the box, and confirm your donation. If you don`t",
    ["STR_ID_InnerPowerNpc[18786][Text274]"] = "~have enough silver, you can exchange your CPs for silver to use.",
    ["STR_ID_InnerPowerNpc[18786][Text275]"] = "Here is a question for you. How much Battle Power can be added to King/ Queen ranked players?",
    ["STR_ID_InnerPowerNpc[18786][Text276]"] = "You mean you saw a potpourri bag just like this before? It must be my nephew, Du San. That poor child. He lost his parents",
    ["STR_ID_InnerPowerNpc[18786][Text277]"] = "Really? You`ve got some clues?",
    ["STR_ID_InnerPowerNpc[18786][Text278]"] = "I need some one to kill those Snake Men. They must pay for their sins.",
    ["STR_ID_InnerPowerNpc[18786][Text279]"] = "He was in Ape City, learning Kungfu. Then our servants reported that he was missing. Several days later,",
    ["STR_ID_InnerPowerNpc[18786][Text280]"] = "Really! It`s about time! It must be those snake bites that made Du San go crazy! Please send this Venomous Fang to",
    ["STR_ID_InnerPowerNpc[18786][Text281]"] = "@STR_COMMON[148]",
    ["STR_ID_InnerPowerNpc[18786][Text282]"] = "@STR_COMMON[148]",
    ["STR_ID_InnerPowerNpc[18786][Text283]"] = "@STR_COMMON[148]",
    ["STR_ID_InnerPowerNpc[18786][Text284]"] = "@STR_COMMON[148]",
    ["STR_ID_InnerPowerNpc[18786][Text285]"] = "@STR_COMMON[148]",
    ["STR_ID_InnerPowerNpc[18786][Text286]"] = "@STR_COMMON[149]",
    ["STR_ID_InnerPowerNpc[18786][Text287]"] = "Snakes! Help!",
    ["STR_ID_InnerPowerNpc[18786][Text288]"] = "What`d happened to me?",
    ["STR_ID_InnerPowerNpc[18786][Text289]"] = "Yes! Thank you! My uncle has given your reward to Taskmaster Chang. Go claim it there!",
    ["STR_ID_InnerPowerNpc[18786][Text290]"] = "Where am I? I remembered I was in Kun Lun... then I was in a dismal abyss... Oh, my head...",
    ["STR_ID_InnerPowerNpc[18786][Text291]"] = "@STR_COMMON[149]",
    ["STR_ID_InnerPowerNpc[18786][Text292]"] = "For what? The story of Kun Lun?",
    ["STR_ID_InnerPowerNpc[18786][Text293]"] = " Oh, this? Well, it was given by a celestial when I visited Kun Lun. Isn`t it elegant?",
    ["STR_ID_InnerPowerNpc[18786][Text294]"] = "@STR_COMMON[673]",
    ["STR_ID_InnerPowerNpc[18786][Text295]"] = "@STR_COMMON[674]",
