    ["STR_ID_InnerPowerNpc[18786][Text506]"] = "@STR_COMMON[549]",
    ["STR_ID_InnerPowerNpc[18786][Text507]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text508]"] = "@STR_COMMON[15]",
    ["STR_ID_InnerPowerNpc[18786][Text509]"] = "Thanks for coming to the Ancestral Hall. They`re all the greatest Guild Leaders of all time!",
    ["STR_ID_InnerPowerNpc[18786][Text510]"] = "You just need to click on the incense burners in front of statues to worship Robin~, iEatBabies and ~*~PureHeart~*~. Each day, you only have one chance to worship one of them.",
    ["STR_ID_InnerPowerNpc[18786][Text511]"] = "xHolic is the leader of the 2nd Supreme Guild MakeMeFamous. Worshipping xHolic will bring you 60 minutes` EXP, 50 Study Points and 1 Chi Token.",
    ["STR_ID_InnerPowerNpc[18786][Text512]"] = "Robin~ is the leader of the 1st Supreme Guild SkillzDatKillz. Worshipping Robin~ will bring you 5 hours` Blessing, 60 minutes` EXP and 1 Chi Token.",
    ["STR_ID_InnerPowerNpc[18786][Text513]"] = "~*~PureHeart~*~ is the leader of the 3rd Supreme Guild Seven?hH??aven. Worshipping ~*~PureHeart~*~ will briing you 5 hours` Blessing, 50 Study Points and 1 Chi Token.",
    ["STR_ID_InnerPowerNpc[18786][Text514]"] = "@STR_COMMON[509]",
    ["STR_ID_InnerPowerNpc[18786][Text515]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text516]"] = "@STR_COMMON[510]",
    ["STR_ID_InnerPowerNpc[18786][Text517]"] = "@STR_COMMON[509]",
    ["STR_ID_InnerPowerNpc[18786][Text518]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text519]"] = "@STR_COMMON[510]",
    ["STR_ID_InnerPowerNpc[18786][Text520]"] = "What are you looking for?",
    ["STR_ID_InnerPowerNpc[18786][Text521]"] = "Well, we are going to take Phoenix Castle, tomorrow. Pass the message to the other remembers and don`t tell anyone else!",
    ["STR_ID_InnerPowerNpc[18786][Text522]"] = "You~are~heading~to~tell~the~Intelligence~Agent~the~news.",
    ["STR_ID_InnerPowerNpc[18786][Text523]"] = "You spy! I`ll kill you!",
    ["STR_ID_InnerPowerNpc[18786][Text524]"] = "\t\tMost Wanted",
    ["STR_ID_InnerPowerNpc[18786][Text525]"] = "Objective: 15 Fire Spirits\n",
    ["STR_ID_InnerPowerNpc[18786][Text526]"] = "I love my family and my village! It is my duty to stay here protect them. It will be great if you can offer me a hand. I will give you some jobs to do. Which one of the following do you want to try?",
    ["STR_ID_InnerPowerNpc[18786][Text527]"] = "@STR_COMMON[26]",
    ["STR_ID_InnerPowerNpc[18786][Text528]"] = "Well done! Maple Forest is a little bit safer, now! Take your reward. You did good, today.",
    ["STR_ID_InnerPowerNpc[18786][Text529]"] = "The AC-Lieutenant in Ape City need our help! I hope you can offer him a hand!",
    ["STR_ID_InnerPowerNpc[18786][Text530]"] = "Speak~with~the~AC-Lieutenant~in~Ape~City!",
    ["STR_ID_InnerPowerNpc[18786][Text531]"] = "This is not a safe place! You have to be careful, if you`re going to wander around, here!",
    ["STR_ID_InnerPowerNpc[18786][Text532]"] = "@STR_COMMON[435]",
    ["STR_ID_InnerPowerNpc[18786][Text533]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text534]"] = "@STR_COMMON[435]",
    ["STR_ID_InnerPowerNpc[18786][Text535]"] = "Would you like to some Fire Spirits! I guarantee you would be well paid!",
    ["STR_ID_InnerPowerNpc[18786][Text536]"] = "I am a soldier! Whether I`m alive or dead, I will fight for my people! But I have many unfinished wishes. I want to return my identity token, and I want my revenge. Will you help me?",
    ["STR_ID_InnerPowerNpc[18786][Text537]"] = "Are you looking for me? I am a dead man now!",
    ["STR_ID_InnerPowerNpc[18786][Text538]"] = "Die! Die! You bastard!",
    ["STR_ID_InnerPowerNpc[18786][Text539]"] = "Please, collect 5 Fury Cores for me! My soul will be appeased.",
    ["STR_ID_InnerPowerNpc[18786][Text540]"] = "I went too deep into this dangerous area and was trapped by the Fire Spirits. I`m a dead man, now.. But I didn`t lost the heart of a soldier! I will keep fighting to save my village! I know these beasts carry Fury Cores to boost their powers. Will you",
    ["STR_ID_InnerPowerNpc[18786][Text541]"] = "This is my identity token... I want you to take it to my Captain. He will know what happen to me when he sees it!",
    ["STR_ID_InnerPowerNpc[18786][Text542]"] = "This is a token used to recognize my identity. I want you to take it to my Captain. He will know what happened to me, when he sees it. I can`t forget Tiger and Dragon. They will always be my friends, even in the afterlife! I will miss them all...",
    ["STR_ID_InnerPowerNpc[18786][Text543]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text544]"] = "It is tough living out here in the wild! I just got a little water left, and unsavoury food to chow. And the worst thing is that we lost one of my team mate.",
    ["STR_ID_InnerPowerNpc[18786][Text545]"] = "Ahhhhhh! Fresh water! You saved my life, man. Nothing like cool water, if you`re standing in this hell! Thank you!",
    ["STR_ID_InnerPowerNpc[18786][Text546]"] = "It`s hard staying near the territory of the Fire Spirits. It`s so hot and I need some water, but I can`t leave my post.",
    ["STR_ID_InnerPowerNpc[18786][Text547]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text548]"] = "I wonder where another of our team, Militia Leopard, might have gone? He has been missing for quite a while. I want to make sure he`s okay. Do you think you could take a look around, and see if you can find him?",
    ["STR_ID_InnerPowerNpc[18786][Text549]"] = "I miss my wife and my son back home. My son`s birthday is also approaching. But I will not come home until those blasted Fire Spirits have all been wiped out!",
    ["STR_ID_InnerPowerNpc[18786][Text550]"] = "Oh, I miss them, too! But I have job to do here! We have to save the village! I can`t just walk away from my duty.",
    ["STR_ID_InnerPowerNpc[18786][Text551]"] = "Wooh! What beautiful teeth you have! I can feel the heat coming off them, from here! My son will love it!",
    ["STR_ID_InnerPowerNpc[18786][Text552]"] = "My son holds great enthusiasm, joy, and pleasure for this world! I want to make him a necklace for his birthday, but I need 10 Fire Spirit Teeth to finish making it. Will you help me to collect some?",
    ["STR_ID_InnerPowerNpc[18786][Text553]"] = "Wait a second, please. My brother, Militia Dragon, needs some water badly. Go help him, if you can!",
    ["STR_ID_InnerPowerNpc[18786][Text554]"] = "I used to spend a night in the hill, alone! Don`t you think I`m brave? If you are also a brave man, I will have some job for you to do. Which of the following quests do you want to try?",
    ["STR_ID_InnerPowerNpc[18786][Text555]"] = "I bet you wouldn`t  even dare to kill a Ratling! If you think you can, kill 10 for me, and I`ll pay you!",
    ["STR_ID_InnerPowerNpc[18786][Text556]"] = "You are great! Thank you! You have definitely earned the right to join my gang! How cool is that?",
    ["STR_ID_InnerPowerNpc[18786][Text557]"] = "You~will~find~some~Ratlings~running~outside~the~village.~go~slay~them.",
    ["STR_ID_InnerPowerNpc[18786][Text558]"] = " I hear that the Fur Dealer is badly in need of some Ratling Fur. I`m sure you`ll be well paid, if you help him!",
    ["STR_ID_InnerPowerNpc[18786][Text559]"] = "Are you going to find the Militia in the forest? Can you take me with you? I miss my father, he has been away from home for over 2 months! No? Can you take this letter to my father? My mother and I miss him, very much! Oh, my father is the Militia Tiger.",
    ["STR_ID_InnerPowerNpc[18786][Text560]"] = "Ratlings have beautiful fur! I can make good money from selling their fur to the other cities.",
    ["STR_ID_InnerPowerNpc[18786][Text561]"] = "Oh! Beautiful, shining fur! I can make good money by selling these. Here is your reward! Thank you, again!",
    ["STR_ID_InnerPowerNpc[18786][Text562]"] = "Let me introduce myself, I am the Fur Dealer! A far travelling businessman, with quite the eye for animals! Would you like to make some money? I need to get 10 Ratling Furs, quick! If you can help, you will be paid handsomely!",
    ["STR_ID_InnerPowerNpc[18786][Text563]"] = "Hey, wait! The Village Head is looking for you, about the Ratling, I guess.",
    ["STR_ID_InnerPowerNpc[18786][Text564]"] = "Phoenix Castle is always our friend! My village is in trouble now, I hope our friends in the Castle can help us out! If you are here to help me, I have a bunch of jobs for you to do! Which of the following quests do you want to try?",
    ["STR_ID_InnerPowerNpc[18786][Text565]"] = "Phoenix Castle will send help to us? Thank you! Thank you, so much!",
    ["STR_ID_InnerPowerNpc[18786][Text566]"] = "You`re welcome! By the way, there`s a Bold Boy who`s going to  kill a Ratling!",
    ["STR_ID_InnerPowerNpc[18786][Text567]"] = "@STR_COMMON[26]",
    ["STR_ID_InnerPowerNpc[18786][Text568]"] = "I am quite impressed by your performance! You really are great! We could use more people like you in the village.",
    ["STR_ID_InnerPowerNpc[18786][Text569]"] = "The Ratlings are out of control! We found that there is an elusive Ratling King, hiding out there. If you killed it, I think the Ratlings would get confused and stop attacking our village. Snake Meat is the favorite food of the Ratling King,",
    ["STR_ID_InnerPowerNpc[18786][Text570]"] = "Good Wine! I could smell it as soon as you were walking up the path! Well, let`s get busy making that lure.",
    ["STR_ID_InnerPowerNpc[18786][Text571]"] = "You must be thinking what I am doing. I will make a lure using the Snake Meat! To make the lure more attractive! I need some Wine! Could you buy a bottle of wine from Deeler Shen?",
    ["STR_ID_InnerPowerNpc[18786][Text572]"] = "@STR_COMMON[434]",
    ["STR_ID_InnerPowerNpc[18786][Text573]"] = "I was quite impressed by you performance! Good job!",
    ["STR_ID_InnerPowerNpc[18786][Text574]"] = "I will soak the Snake Meet in the Wine, so it will take a bit. Why not use this time to slay some Ratlings! This will help make you smell like the Ratlings. That way, it will make it harder for the Ratling King to discover you!",
    ["STR_ID_InnerPowerNpc[18786][Text575]"] = "Good! You have it! Now take a little break. I want study the Frost Token first, and will instruct you on what to do, later.",
    ["STR_ID_InnerPowerNpc[18786][Text576]"] = "You still need a Frost Token. It will provide you with extra defense, especially your resistance against heat! I`ll show you where to find it!",
    ["STR_ID_InnerPowerNpc[18786][Text577]"] = "@STR_COMMON[434]",
    ["STR_ID_InnerPowerNpc[18786][Text578]"] = "I can`t believe my ears! You killed it and saved our village! See? The Ratlings are scattering! Your name will be remembered for as long as our village remains! Thank you, hero!",
    ["STR_ID_InnerPowerNpc[18786][Text579]"] = "Listen! The Ratling King excels at fire attacks. This Frost Token can provide with you extra resistance against heat and fire, for 5 minutes. Use the Wine Soaked Snake to charm it out, then slay it while you`re protected. If you don`t make it in time,",
    ["STR_ID_InnerPowerNpc[18786][Text580]"] = "@STR_COMMON[434]",
    ["STR_ID_InnerPowerNpc[18786][Text581]"] = "Fire Spirits are another big threat to the village! In fact, they`re a threat to Phoenix Castle, too! There are some militiaman fighting desperately against these evil spirits. Maybe you can offer them some help? You can speak with the Militia Captain",
    ["STR_ID_InnerPowerNpc[18786][Text582]"] = "@STR_COMMON[245]",
    ["STR_ID_InnerPowerNpc[18786][Text583]"] = "@STR_COMMON[245]",
    ["STR_ID_InnerPowerNpc[18786][Text584]"] = "Hey, my friend! Welcome to my store. You see, the Bamboo Wine is our best seller. Expensive? Nah, hah. It`s only 10,000",
    ["STR_ID_InnerPowerNpc[18786][Text585]"] = "~Silver for each bottle! Don`t get drunk, ok? Oh, I`ll have a branch in Twin City, soon. You can come and have a drink.",
    ["STR_ID_InnerPowerNpc[18786][Text586]"] = "I tell you, this Bamboo Wine is pretty strong. I`ve never seen one guy buy 2 bottles before. Take care.",
    ["STR_ID_InnerPowerNpc[18786][Text587]"] = "You need 10,000 silvers for this. It`s already the floor price.",
    ["STR_ID_InnerPowerNpc[18786][Text588]"] = "Oh, look at your inventory. I have to remind you that the bottle is very fragile. Make some room for it, first.",
    ["STR_ID_InnerPowerNpc[18786][Text589]"] = " Come! Best wine! Cheap! 1000 gold a bottle! Come! Come! Best wine for sale!",
    ["STR_ID_InnerPowerNpc[18786][Text590]"] = "@STR_COMMON[246]",
    ["STR_ID_InnerPowerNpc[18786][Text591]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text592]"] = "@STR_COMMON[246]",
    ["STR_ID_InnerPowerNpc[18786][Text593]"] = "@STR_COMMON[13]",
    ["STR_ID_InnerPowerNpc[18786][Text594]"] = "He who fights with monsters should take care, lest he wind up becoming a monster, himself! Would you like to help me with any quest?",
    ["STR_ID_InnerPowerNpc[18786][Text595]"] = "I can`t thank you enough. That`s perfect!",
    ["STR_ID_InnerPowerNpc[18786][Text596]"] = "To do a good job, you must first sharpen your tools. I heard that poisonous Snake Scales can make animals dizzy.",
    ["STR_ID_InnerPowerNpc[18786][Text597]"] = "You~are~going~to~kill~Winged~Snakes~and~collect~10~Snake~Scales.",
    ["STR_ID_InnerPowerNpc[18786][Text598]"] = "Have you got some Snake Meat, by the way? Go speak with the Village Head. He`s worried about it.",
    ["STR_ID_InnerPowerNpc[18786][Text599]"] = "@STR_COMMON[430]",
    ["STR_ID_InnerPowerNpc[18786][Text600]"] = "@STR_COMMON[430]",
    ["STR_ID_InnerPowerNpc[18786][Text601]"] = "This letter is very important. Thank you very much!",
    ["STR_ID_InnerPowerNpc[18786][Text602]"] = "@STR_COMMON[431]",
    ["STR_ID_InnerPowerNpc[18786][Text603]"] = "You must be tired. Take a break, buddy.",
    ["STR_ID_InnerPowerNpc[18786][Text604]"] = "What`s the matter? You need to go kill the Bandit Boss!",
    ["STR_ID_InnerPowerNpc[18786][Text605]"] = "@STR_COMMON[431]",
    ["STR_ID_InnerPowerNpc[18786][Text606]"] = "Yes, there is a small village outside the Phoenix Castle in the forest. We maintain a good relationship with the village. Recently, the village was badly damaged by rats. As a neighbor, we need to do something! Will you go see the Village Head first,",
    ["STR_ID_InnerPowerNpc[18786][Text607]"] = "Hey, there! I`m Intelligence Agent. Want to take the quests and destroy Bandits` plots?",
    ["STR_ID_InnerPowerNpc[18786][Text608]"] = "You did a good job!",
    ["STR_ID_InnerPowerNpc[18786][Text609]"] = "You need to get a Bandit`s Coat from the Level 33 Bandits. We will be able to blend in with the rest of the gang, once we have it.",
    ["STR_ID_InnerPowerNpc[18786][Text610]"] = "We have been here trying to collect information for weeks, but haven`t found anything, yet. We are planning to steal a Bandit`s Coat from",
    ["STR_ID_InnerPowerNpc[18786][Text611]"] = "You~are~going~to~get~a~Bandit`s~Coat~from~the~Level~33~Bandits.",
    ["STR_ID_InnerPowerNpc[18786][Text612]"] = "OK. You`ve got the letter. Deliver it to the Phoenix Castellan.",
    ["STR_ID_InnerPowerNpc[18786][Text613]"] = "@STR_COMMON[428]",
    ["STR_ID_InnerPowerNpc[18786][Text614]"] = "That`s great. I`m writing a letter. Please deliver it to the Phoenix Castellan.",
    ["STR_ID_InnerPowerNpc[18786][Text615]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text616]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text617]"] = "@STR_COMMON[428]",
    ["STR_ID_InnerPowerNpc[18786][Text618]"] = "If you happen to be recognized, just try to get another coat from the Level 33 Bandits and try again, later.",
    ["STR_ID_InnerPowerNpc[18786][Text619]"] = "Put on the Bandit`s Coat, and you won`t be recognized. If you happen to be recognized, just try to get another coat from the Level 33 Bandits.",
    ["STR_ID_InnerPowerNpc[18786][Text620]"] = "You need to talk to the Bandit Boss and read the confidential letter. If he asks you what the code is, you should answer `Success is around the corner`.",
    ["STR_ID_InnerPowerNpc[18786][Text621]"] = "You~put~on~the~coat~and~are~going~to~see~the~Bandit~Boss.",
    ["STR_ID_InnerPowerNpc[18786][Text622]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text623]"] = "Hey! Who are you and why are you here? Did you take any quest, or what?",
    ["STR_ID_InnerPowerNpc[18786][Text624]"] = "@STR_COMMON[26]",
    ["STR_ID_InnerPowerNpc[18786][Text625]"] = "Thank god! Please accept these gifts, as thanks. You`ve really managed to get me out of this mess! You`re a lifesaver!",
    ["STR_ID_InnerPowerNpc[18786][Text626]"] = "We got big trouble! Well, we were carrying military supplies to Phoenix Castle, when all of a sudden the Bandits rushed out",
    ["STR_ID_InnerPowerNpc[18786][Text627]"] = "You~are~going~to~get~10~bags~of~grain~from~the~Bandits.",
    ["STR_ID_InnerPowerNpc[18786][Text628]"] = "Listen! Since you`re smart, I`m wondering if you can go help the Intelligence Agent. He`ll give you a challenging mission!",
    ["STR_ID_InnerPowerNpc[18786][Text629]"] = "@STR_COMMON[422]",
    ["STR_ID_InnerPowerNpc[18786][Text630]"] = "@STR_COMMON[422]",
    ["STR_ID_InnerPowerNpc[18786][Text631]"] = "@STR_COMMON[422]",
    ["STR_ID_InnerPowerNpc[18786][Text632]"] = "@STR_COMMON[422]",
    ["STR_ID_InnerPowerNpc[18786][Text633]"] = "@STR_COMMON[422]",
    ["STR_ID_InnerPowerNpc[18786][Text634]"] = "Great! You are my hero!",
    ["STR_ID_InnerPowerNpc[18786][Text635]"] = "Haha, hi! Are you looking for me? Do you want to play a game? Let`s play hide-and-seek!",
    ["STR_ID_InnerPowerNpc[18786][Text636]"] = "But I`m still waiting for my dad. You see those Bandits, over there? What if my dad walks home at night and they see him?",
    ["STR_ID_InnerPowerNpc[18786][Text637]"] = "You~are~going~to~kill~10~Bandits.",
    ["STR_ID_InnerPowerNpc[18786][Text638]"] = "Give me a break! I need to focus, if I`m going to spot Dad, in time. Can you go first, and tell my mum that I will be home soon?",
    ["STR_ID_InnerPowerNpc[18786][Text639]"] = "You~are~on~the~way~to~see~Yu~Lin.",
    ["STR_ID_InnerPowerNpc[18786][Text640]"] = "@STR_COMMON[421]",
    ["STR_ID_InnerPowerNpc[18786][Text641]"] = "@STR_COMMON[421]",
    ["STR_ID_InnerPowerNpc[18786][Text642]"] = "@STR_COMMON[421]",
    ["STR_ID_InnerPowerNpc[18786][Text643]"] = "@STR_COMMON[421]",
    ["STR_ID_InnerPowerNpc[18786][Text644]"] = "What? My husband is dead? You can`t be serious!",
    ["STR_ID_InnerPowerNpc[18786][Text645]"] = "My daughter, Yu Jing, goes to the northwest everyday, in hopes that she can see her father returning home.",
    ["STR_ID_InnerPowerNpc[18786][Text646]"] = "You~are~on~the~way~to~look~for~Yu~Jing.",
    ["STR_ID_InnerPowerNpc[18786][Text647]"] = "@STR_COMMON[422]",
    ["STR_ID_InnerPowerNpc[18786][Text648]"] = "Why are you alone? Where`s my daughter?",
    ["STR_ID_InnerPowerNpc[18786][Text649]"] = "@STR_COMMON[3]",
    ["STR_ID_InnerPowerNpc[18786][Text650]"] = "A holy habit cannot cleanse a foul soul. What can I do for you, my child?",
    ["STR_ID_InnerPowerNpc[18786][Text651]"] = "I just found this letter. It was a poem written by a villager, specially for his wife.",
    ["STR_ID_InnerPowerNpc[18786][Text652]"] = "I have a bad feeling that awful things are going to happen in Phoenix Castle.",
    ["STR_ID_InnerPowerNpc[18786][Text653]"] = "You~were~teleported~to~Phoenix~Castle.~Hurry~to~visit~the~Forest~Governor!",
    ["STR_ID_InnerPowerNpc[18786][Text654]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text655]"] = "Hello, there! Would you like to challenge the Eight-Diagram Dimensions, or any other quests?",
    ["STR_ID_InnerPowerNpc[18786][Text656]"] = "@STR_COMMON[690]",
    ["STR_ID_InnerPowerNpc[18786][Text657]"] = "I have been studying about spirits for years. Recently I invented this Spirit Container, but I`m not sure if it works.",
    ["STR_ID_InnerPowerNpc[18786][Text658]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text659]"] = "The Spirit Container is working! Thanks a million!",
    ["STR_ID_InnerPowerNpc[18786][Text660]"] = "Please take this Spirit Container and head out to capture the spirits of 10 Apparitions.",
    ["STR_ID_InnerPowerNpc[18786][Text661]"] = "@STR_COMMON[690]",
    ["STR_ID_InnerPowerNpc[18786][Text662]"] = "Please visit Master Hao and ask him how to break the seal that is binding the spirits.",
    ["STR_ID_InnerPowerNpc[18786][Text663]"] = "@STR_COMMON[418]",
    ["STR_ID_InnerPowerNpc[18786][Text664]"] = "What are you doing back here, so soon? Did my love enjoy the handkerchief? I do hope so!",
    ["STR_ID_InnerPowerNpc[18786][Text665]"] = "@STR_COMMON[418]",
    ["STR_ID_InnerPowerNpc[18786][Text666]"] = "@STR_COMMON[419]",
    ["STR_ID_InnerPowerNpc[18786][Text667]"] = "@STR_COMMON[420]",
    ["STR_ID_InnerPowerNpc[18786][Text668]"] = "I`ve sewn some patterns on the handkerchief. Could you please help me to send this Mandarin Duck Hanky to Xu Liang?",
    ["STR_ID_InnerPowerNpc[18786][Text669]"] = "@STR_COMMON[420]",
    ["STR_ID_InnerPowerNpc[18786][Text670]"] = "@STR_COMMON[420]",
    ["STR_ID_InnerPowerNpc[18786][Text671]"] = "You mean Xu Liang wants to take me on a date beside the river, tonight? Okay, I see. Thanks for telling me! I`d love to!",
    ["STR_ID_InnerPowerNpc[18786][Text672]"] = "It`s said that the Fortuneteller nearby has been studying spirits for years and recently invented some new things.",
    ["STR_ID_InnerPowerNpc[18786][Text673]"] = "Yes! This is the Handkerchief I made it, myself. Thanks for your help!",
    ["STR_ID_InnerPowerNpc[18786][Text674]"] = "I`ve sewn some beautiful patterns on this handkerchief. Could you please help me send this Mandarin Duck Hanky to Xu Liang?",
    ["STR_ID_InnerPowerNpc[18786][Text675]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text676]"] = "Wow, a Bouquet of Peach Blossoms! It`s from Xu Liang? Well, why don`t he send this by himself?",
    ["STR_ID_InnerPowerNpc[18786][Text677]"] = "@STR_COMMON[419]",
    ["STR_ID_InnerPowerNpc[18786][Text678]"] = "@STR_COMMON[413]",
    ["STR_ID_InnerPowerNpc[18786][Text679]"] = "@STR_COMMON[414]",
    ["STR_ID_InnerPowerNpc[18786][Text680]"] = "My mission is to ensure the security and peace of Twin City. Hey, how is it going?",
    ["STR_ID_InnerPowerNpc[18786][Text681]"] = "@STR_COMMON[413]",
    ["STR_ID_InnerPowerNpc[18786][Text682]"] = "@STR_COMMON[26]",
    ["STR_ID_InnerPowerNpc[18786][Text683]"] = "Good job! Thanks for your help! Here is a reward for you. Take it!",
    ["STR_ID_InnerPowerNpc[18786][Text684]"] = "My mission is to ensure the security and peace of Twin City. You still want to take the Robins Elimination quest?",
    ["STR_ID_InnerPowerNpc[18786][Text685]"] = "@STR_COMMON[413]",
    ["STR_ID_InnerPowerNpc[18786][Text686]"] = "@STR_COMMON[415]",
    ["STR_ID_InnerPowerNpc[18786][Text687]"] = "@STR_COMMON[415]",
    ["STR_ID_InnerPowerNpc[18786][Text688]"] = "Well, I`ve made a Bouquet of Peach Blossoms , but I`m afraid that she may refuse me when she saw the flowers...",
    ["STR_ID_InnerPowerNpc[18786][Text689]"] = "@STR_COMMON[413]",
    ["STR_ID_InnerPowerNpc[18786][Text690]"] = "Wow, Ru Hua asked you to give me this Mandarin Duck Hanky? How terrific! She has accepted my love! I`m so happy! ",
    ["STR_ID_InnerPowerNpc[18786][Text691]"] = "@STR_COMMON[414]",
    ["STR_ID_InnerPowerNpc[18786][Text692]"] = "@STR_COMMON[414]",
    ["STR_ID_InnerPowerNpc[18786][Text693]"] = "Well, I`ve made a bouquet of peach blossoms, but I`m afraid that she may refuse me when she sees the flowers... ",
    ["STR_ID_InnerPowerNpc[18786][Text694]"] = "My mission is to ensure the security and peace of Twin City. Well, I do need your help again. You won`t say no, right? ",
    ["STR_ID_InnerPowerNpc[18786][Text695]"] = "@STR_COMMON[416]",
    ["STR_ID_InnerPowerNpc[18786][Text696]"] = " Wow, look at the beautiful peach blossoms! Thanks a lot! I`ll make a bouquet of peach blossoms and give them to Ru Hua!",
    ["STR_ID_InnerPowerNpc[18786][Text697]"] = "@STR_COMMON[417]",
    ["STR_ID_InnerPowerNpc[18786][Text698]"] = "@STR_COMMON[417]",
    ["STR_ID_InnerPowerNpc[18786][Text699]"] = "Oh, it`s a Plume Letter from the TC Vice Captain! Something must be urgent. Thanks for your help!",
    ["STR_ID_InnerPowerNpc[18786][Text700]"] = "Recently, lots of robins invaded the Wind Plain. Could you go kill 5 Robins and restore peace to Wind Plain?",
    ["STR_ID_InnerPowerNpc[18786][Text701]"] = "Oh, where it`s a Plume Letter from the TC Vice Captain?",
    ["STR_ID_InnerPowerNpc[18786][Text702]"] = "My mission is to ensure the security and peace of Twin City. Hey, I have 2 quests for you: Robins Elimination and Love Confession. Which one are you interested in?",
    ["STR_ID_InnerPowerNpc[18786][Text703]"] = "By the way, Artisan Luo is looking for someone to help him gather some Robin Feather. Maybe you can give him a hand?",
    ["STR_ID_InnerPowerNpc[18786][Text704]"] = "Good. Then go kill 10 Robins and restore peace to Wind Plain!",
    -- {0}=spell.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text705]"] = "In this dangerous world, a powerful XP skill can make you stronger. Now I`ll teach you a unique XP skill, {0}",
    ["STR_ID_InnerPowerNpc[18786][Text706]"] = "The Trojans have unique XP skill which disguises them as a robot and wreaks havoc amongst enemies.",
    ["STR_ID_InnerPowerNpc[18786][Text707]"] = "The 'Superman' XP Skill is unique, possessed only by the Warrior. When activated it causes a death blow, decupled damage!",
    ["STR_ID_InnerPowerNpc[18786][Text708]"] = "The ability to 'Fly' is the unique ability of the archer. Archers who fly are ",
    ["STR_ID_InnerPowerNpc[18786][Text709]"] = "The ninja's skills can cause massive damage in a split second, or disable enemies, or prevent them from healing themselves.\n\n",
    ["STR_ID_InnerPowerNpc[18786][Text710]"] = "Move speed will increase. Inflict 200% damage on targets. For each monster killed within ",
    ["STR_ID_InnerPowerNpc[18786][Text711]"] = "(Cannon Barrage)  Inflict 400% damage on all monsters (100% damage on bosses), 10% of normal damage ",
    ["STR_ID_InnerPowerNpc[18786][Text712]"] = "The XP skill needs a certain period of time to accumulate its power. Once cast, you can kill a lot of monsters in a very short time. ",
    ["STR_ID_InnerPowerNpc[18786][Text713]"] = "Taoists with no magic is a sitting duck. They cast skills or magic from range and their  ",
    ["STR_ID_InnerPowerNpc[18786][Text714]"] = "Windwalker XP skill. Equip Windwalker fan in both hands to cast. Cast it to enter Omnipotence status which deals 10% of ",
    ["STR_ID_InnerPowerNpc[18786][Text715]"] = "Use your XP skill to kill 100 Robins!",
    ["STR_ID_InnerPowerNpc[18786][Text716]"] = "Hi! I`m the TC Vice Captain, and I`m here to guard Twin City. Hey, do you think you can help me deliver a letter?",
    ["STR_ID_InnerPowerNpc[18786][Text717]"] = "Hi! I`m the TC Vice Captain, and I`m here to guard Twin City. Don`t make trouble, or we`re going to have problems!",
    ["STR_ID_InnerPowerNpc[18786][Text718]"] = "Well done! You`ve got the letter. Thanks a lot!",
    ["STR_ID_InnerPowerNpc[18786][Text719]"] = "I want you to deliver a letter to Xu Liang, but the letter is being held by the Warehouseman. Could you please get it back for me?",
    ["STR_ID_InnerPowerNpc[18786][Text720]"] = "Hi! I`m the TC Vice Captain, and I`m here to guard Twin City. Hmm, do you want to take the quest `Letter Delivery 2`?",
    ["STR_ID_InnerPowerNpc[18786][Text721]"] = "The Military Letter is quite important, so I need a Turtledove Plume to mark the letter. Could you please hunt some Turtledoves and bring back a Turtledove Plume for me?",
    ["STR_ID_InnerPowerNpc[18786][Text722]"] = "@STR_COMMON[26]",
    ["STR_ID_InnerPowerNpc[18786][Text723]"] = "Now, please hurry and deliver the Military Letter marked with the Turtledove Plume to Xu Liang in Wind Plain! It`s urgent!",
    ["STR_ID_InnerPowerNpc[18786][Text724]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text725]"] = "Now, please hurry and deliver the Plume Letter to Xu Liang in Wind Plain! It`s urgent!",
    ["STR_ID_InnerPowerNpc[18786][Text726]"] = "We~hope~all~can~help~each~other.~If~you~power~level~the~newbies,~we~may~reward~you~Experience~or~meteors.~Are~you~interested?",
    ["STR_ID_InnerPowerNpc[18786][Text727]"] = "If~you~are~above~level~70~and~try~to~power~level~the~newbies~(at~least~20~levels~lower~than~you),~you~may~gain~virtue~points.",
    ["STR_ID_InnerPowerNpc[18786][Text728]"] = "The~more~newbies~you~power~level,~the~more~virtue~points~you~gain.~I~shall~give~you~a~good~reward~for~a~certain~virtue~points.",
    ["STR_ID_InnerPowerNpc[18786][Text729]"] = "Once~the~newbies~are~one~level~up,~the~team~captain~can~gain~virtue~points~accordingly.",
    ["STR_ID_InnerPowerNpc[18786][Text730]"] = "I~shall~reward~you~exp.~of~equivalent~to~an~ExpBall~for~15,000~virtue~points~or~a~meteor~for~5000~virtue~points or DragonBall for 20,000 virtue~points.",
    -- {0}=client.Player.VirtutePoints
    ["STR_ID_InnerPowerNpc[18786][Text731]"] = "Your~current~virtue~points~are~{0},~please~try~to~gain~more.",
    ["STR_ID_InnerPowerNpc[18786][Text732]"] = "What~prize~do~you~prefer?",
    ["STR_ID_InnerPowerNpc[18786][Text733]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text734]"] = "@STR_COMMON[691]",
    ["STR_ID_InnerPowerNpc[18786][Text735]"] = "Only the characters below level 130 can exchange the virtue points for exp. You may find Simon",
    ["STR_ID_InnerPowerNpc[18786][Text736]"] = "@STR_COMMON[691]",
    ["STR_ID_InnerPowerNpc[18786][Text737]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text738]"] = "@STR_COMMON[691]",
    ["STR_ID_InnerPowerNpc[18786][Text739]"] = "When you burn a [RosewoodIncrense], you`ll feel refreshed and clear-minded. ",
    ["STR_ID_InnerPowerNpc[18786][Text740]"] = "Diffrent gift requires diffrent amount of RoseWood incense. Here's an exchange ",
    ["STR_ID_InnerPowerNpc[18786][Text741]"] = "Please come back when you will have 20 RosewoodIncense in your inventory.",
    ["STR_ID_InnerPowerNpc[18786][Text742]"] = "Please come back when you will have 10 RosewoodIncense in your inventory.",
