    ["STR_ID_InnerPowerNpc[18786][Text745]"] = "The mortal world is stil the best place for me . I received anlghtement here thousands years ago . ",
    ["STR_ID_InnerPowerNpc[18786][Text746]"] = "Are you sure you want to start this trial with the power of Buddha`sNecklace?",
    ["STR_ID_InnerPowerNpc[18786][Text747]"] = "Please come back when you will have 1 Buddha`sNecklace in your inventory.",
    ["STR_ID_InnerPowerNpc[18786][Text748]"] = "Why did you keep me waiting so long ? Well i'm not wordy. To many Emotions and desires will ",
    ["STR_ID_InnerPowerNpc[18786][Text749]"] = "@STR_COMMON[692]",
    ["STR_ID_InnerPowerNpc[18786][Text750]"] = "Please come back when you will have 1 SpiritualGem in your inventory.",
    ["STR_ID_InnerPowerNpc[18786][Text751]"] = "@STR_COMMON[692]",
    ["STR_ID_InnerPowerNpc[18786][Text752]"] = "Please come back when you will have 5 SpiritualGem in your inventory.",
