    ["STR_ID_InnerPowerNpc[18786][Text826]"] = "Hello, can you help me? If you kill the required monsters I desire you can win some EXP. You must kill {0} monsters.",
    ["STR_ID_InnerPowerNpc[18786][Text827]"] = "Please make 2 empty space in your inventory to receive the reward for passing the 2nd level.",
    -- {0}=MsgTournaments.MsgSchedules.DisCity.KillsMap2Records(client.Player.Class)
    ["STR_ID_InnerPowerNpc[18786][Text828]"] = "You`ll~pass~if~you~kill~{0}~monsters~in~HellHall.~Hurry~up!~Only~30~persons~can~get~to~HellCloister~with~me.",
    ["STR_ID_InnerPowerNpc[18786][Text829]"] = "Well, now that you`ve got 5 Soul Stones, I`ll give you 2 Exp Ball(B), a Cordiality Book(B), an Exp Pill(B) and a Dis City Bless Stone(12H)(B). Then, send you to the next level. Are you ready?",
