    ["STR_ID_InnerPowerNpc[18786][Text832]"] = "@STR_COMMON[96]",
    ["STR_ID_InnerPowerNpc[18786][Text833]"] = "The decisive battle bewtween human and the demon broke out here. The ferocious battle lasted for seven days and nights. Countless heroes lost their",
    ["STR_ID_InnerPowerNpc[18786][Text834]"] = "UltimatePluto, leader of the demons sworn to take revenge in one thousand  years befote he managed to run away. To prevent the demons coming back, I",
    ["STR_ID_InnerPowerNpc[18786][Text835]"] = "Fortunately UltimatePluto is still unfledged. He must resort to a Battle Formation for the moments. So i am about to organize an army too infiltrate his",
    ["STR_ID_InnerPowerNpc[18786][Text836]"] = "You must kill UltimatePluto rapisly to get Darkhorn so that i can use it to diable the formation. Before you can do that, you must break into HellGate,",
    ["STR_ID_InnerPowerNpc[18786][Text837]"] = "HellGate is shielded from poisonous fog, so you can't approach it. But demons do not fear the gas. They may turn into SoulStones after they die. If",
    ["STR_ID_InnerPowerNpc[18786][Text838]"] = "HellHall is the very spot where the demons swear their oaths of allegiance to UltimatePluto. Everybody must do his best to make a way out. Due to limited",
    ["STR_ID_InnerPowerNpc[18786][Text839]"] = "You will be divided into 2 groups to attack from the left and the right flank of HellCloister. Kill the Wraithas many as you can, because you can't reach",
    ["STR_ID_InnerPowerNpc[18786][Text840]"] = "BattleFormation is protected by Syrens. After they are killed out, UltimatePluto will appear. Make the best effort to kill him, get his Darkhorn",
    ["STR_ID_InnerPowerNpc[18786][Text841]"] = "@STR_COMMON[97]",
    ["STR_ID_InnerPowerNpc[18786][Text842]"] = "@STR_COMMON[98]",
    ["STR_ID_InnerPowerNpc[18786][Text843]"] = "Kill~the~demons~to~gather~five~SoulStones.~Then~go~northeast~through~HellBridge,~and~look~for~me~at~HellGate.",
    ["STR_ID_InnerPowerNpc[18786][Text844]"] = "You`re~not~strong~enough~for~the~moment.~Don`t~lose~your~life~in~vain.",
    ["STR_ID_InnerPowerNpc[18786][Text845]"] = "Please sign up between 7:30-7:35 and 17:30-17:35 every day, except Sundays.",
    ["STR_ID_InnerPowerNpc[18786][Text846]"] = "@STR_COMMON[495]",
    ["STR_ID_InnerPowerNpc[18786][Text847]"] = "@STR_COMMON[495]",
    ["STR_ID_InnerPowerNpc[18786][Text848]"] = "@STR_COMMON[495]",
    ["STR_ID_InnerPowerNpc[18786][Text849]"] = "The Stone Ape was born from the rock used to restore cracks in the sky. He never know about it. He gets potentials. If guided properly, he can be a great immortal!",
    ["STR_ID_InnerPowerNpc[18786][Text850]"] = "I have a Divine Calix. Get some water from the fountain in the Maple Forest. It will help the Stone Ape to unleash his potential!",
    ["STR_ID_InnerPowerNpc[18786][Text851]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text852]"] = "@STR_COMMON[96]",
    -- {0}=client.Player.Name
    ["STR_ID_InnerPowerNpc[18786][Text853]"] = "Hey there {0}! The race is held every two hours, on even hours(11,15,23,..). Are you interested in joining the race? You might receive amazing gifts upon reaching the finish line!",
    ["STR_ID_InnerPowerNpc[18786][Text854]"] = "You need a horse first.",
    ["STR_ID_InnerPowerNpc[18786][Text855]"] = "You need to learn the ride spell first!",
    ["STR_ID_InnerPowerNpc[18786][Text856]"] = "Please sign up at 11:00 AM and 15:00 and 23:00 every day.",
    ["STR_ID_InnerPowerNpc[18786][Text857]"] = "Glad to see you! I take it that you haven`t heard of the TeamDeathMatch tournament? please allow me to introduce this exciting event for you.",
    ["STR_ID_InnerPowerNpc[18786][Text858]"] = "@STR_COMMON[44]",
    ["STR_ID_InnerPowerNpc[18786][Text859]"] = "@STR_COMMON[44]",
    ["STR_ID_InnerPowerNpc[18786][Text860]"] = "Glad to see you! I take it that you haven`t heard of the ExtremePk tournament? please allow me to introduce this exciting event for you.",
    ["STR_ID_InnerPowerNpc[18786][Text861]"] = "@STR_COMMON[44]",
    ["STR_ID_InnerPowerNpc[18786][Text862]"] = "@STR_COMMON[44]",
    ["STR_ID_InnerPowerNpc[18786][Text863]"] = "King of the Hill is a gear based free for all event. Players gain points by",
