    ["STR_ID_InnerPowerNpc[18786][Text865]"] = "@STR_COMMON[44]",
    ["STR_ID_InnerPowerNpc[18786][Text866]"] = "Glad to see you! I take it that you haven`t heard of the BestKiller tournament? please allow me to introduce this exciting event for you.",
    ["STR_ID_InnerPowerNpc[18786][Text867]"] = "@STR_COMMON[44]",
    ["STR_ID_InnerPowerNpc[18786][Text868]"] = "@STR_COMMON[44]",
    ["STR_ID_InnerPowerNpc[18786][Text869]"] = "Glad to see you! I take it that you haven`t heard of the DBShower tournament? please allow me to introduce this exciting event for you.",
