    ["STR_ID_InnerPowerNpc[18786][Text872]"] = "Hey, I`m proficient in repairing max Durability. What items do you wana me to repair?",
    ["STR_ID_InnerPowerNpc[18786][Text873]"] = "What Talisman do you want me to repair?",
    ["STR_ID_InnerPowerNpc[18786][Text874]"] = "Sorry, please ask a shopkeeper to repair this item first. I only repair the max durability.",
