    ["STR_ID_InnerPowerNpc[18786][Text925]"] = "The new Skill Team Pk Tournament is open! It is held at 21:55,every",
    ["STR_ID_InnerPowerNpc[18786][Text926]"] = "There are limits on the Equipmen Level and Rank. Moreover, there are",
    ["STR_ID_InnerPowerNpc[18786][Text927]"] = "here Skill Team Pk Tournament is held at 21:55 , every day. You need",
    ["STR_ID_InnerPowerNpc[18786][Text928]"] = "You can talk to me to enter the Waiting area at 21:55. No threams will be allowed to enter ",
    ["STR_ID_InnerPowerNpc[18786][Text929]"] = "@STR_COMMON[425]",
    ["STR_ID_InnerPowerNpc[18786][Text930]"] = "Please sign up between 21:55 and 21:59 every Wednesday night for the Skill PK Tournament.",
    ["STR_ID_InnerPowerNpc[18786][Text931]"] = "Sorry, you are not in top 8 in Skill Pk Tournament or you claimed the reward.",
    ["STR_ID_InnerPowerNpc[18786][Text932]"] = "@STR_COMMON[426]",
    ["STR_ID_InnerPowerNpc[18786][Text933]"] = "Attention! The Team Pk Tournament is held at 18:55, each Thursday. The Top 8",
    ["STR_ID_InnerPowerNpc[18786][Text934]"] = "The Team Pk Tournament start at 18:55 every Thursday, and teams will be divided",
    ["STR_ID_InnerPowerNpc[18786][Text935]"] = "@STR_COMMON[425]",
    ["STR_ID_InnerPowerNpc[18786][Text936]"] = "Please sign up at 18:55 every Thursday     night for the Team PK Tournament.",
    ["STR_ID_InnerPowerNpc[18786][Text937]"] = "Sorry, you are not in top 8 in Team Pk Tournament or you claimed the reward.",
    ["STR_ID_InnerPowerNpc[18786][Text938]"] = "@STR_COMMON[426]",
    ["STR_ID_InnerPowerNpc[18786][Text939]"] = "Glad to see you! I take it that you haven`t heard of the Elite PK Tournament, have you? No? Aha, please allow me to",
    ["STR_ID_InnerPowerNpc[18786][Text940]"] = "The Elite PK Tournament begins at 20:00 every Friday night, and players will be divided into four groups, which are the Under 100 group, the 100-119 group, the 120-129 group, and the 130+ group. You can sign up for it",
    ["STR_ID_InnerPowerNpc[18786][Text941]"] = "Sure. When there are less than 8 players left in the field, the Final starts. Each round of the Final lasts for 5 minutes. Though all of the Top 8 players will receive nice prizes, the top 3 will earn special prizes! Claim your reward before the next",
    ["STR_ID_InnerPowerNpc[18786][Text942]"] = "Please sign up between 19:55 and 19:59 every Friday night for the Elite PK Tournament.",
    ["STR_ID_InnerPowerNpc[18786][Text943]"] = "Sorry, you are not in top 8 in elite pk or you claimed the reward.",
    ["STR_ID_InnerPowerNpc[18786][Text944]"] = "Please make 1 more space in your bag.",
    ["STR_ID_InnerPowerNpc[18786][Text945]"] = "Hello , you're the last player alive?",
    ["STR_ID_InnerPowerNpc[18786][Text946]"] = "@STR_COMMON[470]",
    ["STR_ID_InnerPowerNpc[18786][Text947]"] = "Sorry, the war is not finished, or other players are still alive.",
    ["STR_ID_InnerPowerNpc[18786][Text948]"] = "Sorry, the war is not finished",
    ["STR_ID_InnerPowerNpc[18786][Text949]"] = "Sorry, the war is finished, or other players are still alive.",
    ["STR_ID_InnerPowerNpc[18786][Text950]"] = "You wana to teleport back to TwinCity? You are sure?",
    ["STR_ID_InnerPowerNpc[18786][Text951]"] = "Everyone settle down! I need to announce that there are new rules for the Class PK War!",
    ["STR_ID_InnerPowerNpc[18786][Text952]"] = "@STR_COMMON[43]",
    ["STR_ID_InnerPowerNpc[18786][Text953]"] = "@STR_COMMON[43]",
    ["STR_ID_InnerPowerNpc[18786][Text954]"] = "With only 100 silver, I can teleport you to somewhere far away. Please choose your destination.",
    ["STR_ID_InnerPowerNpc[18786][Text955]"] = "@STR_COMMON[502]",
    ["STR_ID_InnerPowerNpc[18786][Text956]"] = "@STR_COMMON[502]",
    ["STR_ID_InnerPowerNpc[18786][Text957]"] = "I`m sell WindSpell for 1.000 Silver. Use that to teleport back to me",
