    ["STR_ID_InnerPowerNpc[18786][Text970]"] = "Lucky~for~you,~the~player~who~killed~you~is~willing~to~drop~the~murder~charges~if~you~pay~him~according~to~what~you~did.",
    ["STR_ID_InnerPowerNpc[18786][Text971]"] = "The~red~name,~whose~PK~points~are~30-99,~can~leave~here~without~any~price.~The~black~name,~whose~PK~points~are~100~",
