    ["STR_ID_InnerPowerNpc[18786][Text1025]"] = "Tell you what, there`s a monster called Nemesis Tyrant hiding at the bottom of the Bloodshed Sea! No one has come back alive after seeing it!",
    ["STR_ID_InnerPowerNpc[18786][Text1026]"] = "This is where the Nemesis Tyrant is hiding. I can`t recall the number of the people who came here. I just remember how they got killed. If you wanna",
    ["STR_ID_InnerPowerNpc[18786][Text1027]"] = "This is where the Nemesis Tyrant is hiding. I can`t recall the number of the people who came here. I just remember how they got killed. If you wanna",
    ["STR_ID_InnerPowerNpc[18786][Text1028]"] = "Well, this sea is kinda special. You won`t get PK points and can`t use City Gates. The Nemesis Tyrant will show up at 15 and 45 of each hour. Look at you...",
