    ["STR_ID_InnerPowerNpc[18786][Text1053]"] = "Please take 25000 cps .",
    ["STR_ID_InnerPowerNpc[18786][Text1054]"] = "@STR_COMMON[492]",
    ["STR_ID_InnerPowerNpc[18786][Text1055]"] = "Hello , Here 4.000.000.000 Milyaer Coin For 100.000 CPS.",
    ["STR_ID_InnerPowerNpc[18786][Text1056]"] = "You not have 100.000 CPS with you.",
    ["STR_ID_InnerPowerNpc[18786][Text1057]"] = "You not have 4.000.000.000 Money with you.",
    ["STR_ID_InnerPowerNpc[18786][Text1058]"] = "Hello , I'm here to dance PK .",
    ["STR_ID_InnerPowerNpc[18786][Text1059]"] = "You not have 1 CPS with you.",
    ["STR_ID_InnerPowerNpc[18786][Text1060]"] = "We Made it Easy For You, From Here You can Go To All Server Monsters.",
    ["STR_ID_InnerPowerNpc[18786][Text1061]"] = "<tip desc=Cobb#Wind,#formerly#a#pirate,#was#save#by#Sky#Shan#from#a#murder.#",
    ["STR_ID_InnerPowerNpc[18786][Text1062]"] = "He#has#turned#to#the#side#of#justice#since#then,#and#made#lots#of#contributions.>",
    ["STR_ID_InnerPowerNpc[18786][Text1063]"] = "Cobb Wind</tip>:                                                                                                                       ",
    ["STR_ID_InnerPowerNpc[18786][Text1064]"] = "You came at the right time! The devils have occupied the Twisting Hell Array, and are trying to summon",
    ["STR_ID_InnerPowerNpc[18786][Text1065]"] = "<tip color=0xfff05050 desc=Killing#Nemesis#Tyrant#brings#Savage#Bone,#P7#Weapon/Armor/Accessory#Soul#Pack#Fragment,#Senior#EXP#Nut,#etc.>Nemesis Tyrant</tip>,",
    ["STR_ID_InnerPowerNpc[18786][Text1066]"] = "~<tip color=0xfff05050 desc=Killing#Snow#Banshee#brings#P5-6#Dragon#Soul,#Dragon#Ball,#+2#Stone,#Senior#EXP#Nut,#etc.>Snow Banshee</tip> and",
    ["STR_ID_InnerPowerNpc[18786][Text1067]"] = "~<tip color=0xfff05050 desc=Killing#Thrilling#Spook#brings#P6#Dragon#Soul,#Dragon#Ball,#Senior#EXP#Nut,#etc.>Thrilling Spook</tip>",
    ["STR_ID_InnerPowerNpc[18786][Text1068]"] = "~to the Dragon Island. Commander Shan has given order to kill them at any cost. Dragon Island is not allowed to sink!                                                          ",
    -- {0}=DateTime.Now.AddHours(1).Hour
    ["STR_ID_InnerPowerNpc[18786][Text1069]"] = "\t* [Thrilling Spook] will appear at {0}:00 today around (349,635) on the Dragon Island.* ",
    -- {0}=DateTime.Now.Hour
    ["STR_ID_InnerPowerNpc[18786][Text1070]"] = "\t* [Nemesis Tyrant] will appear at {0}:17 today around (568,372) on the Dragon Island.* ",
    -- {0}=DateTime.Now.Hour
    ["STR_ID_InnerPowerNpc[18786][Text1071]"] = "\t* [Snow Banshee] will appear at {0}:27 today around (658,718) on the Dragon Island.* ",
    ["STR_ID_InnerPowerNpc[18786][Text1072]"] = "@STR_COMMON[708]",
    ["STR_ID_InnerPowerNpc[18786][Text1073]"] = "    [Beast]                    [Location]       \t\t[Appear Time]                                            ",
    ["STR_ID_InnerPowerNpc[18786][Text1074]"] = "Nemesis Tyrant    (DragonIsland 568,372)\t   the 15th and 45th minute of each hour, every day                                                                                                       ",
    ["STR_ID_InnerPowerNpc[18786][Text1075]"] = "Thrilling Spook\t (DragonIsland 349,635)   the 00th and 30th minute of each hour, every day                                                                                                           ",
    ["STR_ID_InnerPowerNpc[18786][Text1076]"] = "Snow Banshee\t (DragonIsland 658,718)   the 27th and 57th minute of each hour, every day                                                                                                               ",
    ["STR_ID_InnerPowerNpc[18786][Text1077]"] = "@STR_COMMON[708]",
    ["STR_ID_InnerPowerNpc[18786][Text1078]"] = "All the beasts above have left their lair for the Dragon Island.",
    ["STR_ID_InnerPowerNpc[18786][Text1079]"] = "The beast must be killed without any delay. You can find it with pathfinding or pay 1 CP to instantly get teleported.",
    ["STR_ID_InnerPowerNpc[18786][Text1080]"] = "<tip desc=In#the#battle#several#hundred#years#ago,#the#Five#Great#Masters#defeated#the#King#of#Evil#and#destroyed#his#Twisting#Hell#Array#",
    ["STR_ID_InnerPowerNpc[18786][Text1081]"] = "on#the#Dragon#Island.#After#that,#11#heroes#volunteered#to#station#on#the#island.#Iron#Tong#has#inherited#this#mission#more#than#ten#years.#",
    ["STR_ID_InnerPowerNpc[18786][Text1082]"] = "However,#the#hell#devils#broke#in#again.#To#get#out#of#this#crisis,#he#left#Dragon#Island#for#the#first#time.>Iron Tong</tip>: ",
    ["STR_ID_InnerPowerNpc[18786][Text1083]"] = "The Queen of Evil and her troop suddenly attacked the Dragon Island. Obviously, she came for the Twisting Hell Array.",
    ["STR_ID_InnerPowerNpc[18786][Text1084]"] = "~I`m afraid she has figured out how to reactivate that array. We`d better not to let it happen. For the sake of humans,",
    ["STR_ID_InnerPowerNpc[18786][Text1085]"] = "~please join us to defend the Dragon Island!",
    ["STR_ID_InnerPowerNpc[18786][Text1086]"] = "@STR_COMMON[709]",
    ["STR_ID_InnerPowerNpc[18786][Text1087]"] = "@STR_COMMON[709]",
    ["STR_ID_InnerPowerNpc[18786][Text1088]"] = "@STR_COMMON[709]",
    ["STR_ID_InnerPowerNpc[18786][Text1089]"] = "@STR_COMMON[709]",
    ["STR_ID_InnerPowerNpc[18786][Text1090]"] = "There`s a mysterious treasure sealed since the ancient times. With a Savage Bone, you can explore and have a chance to get Sacred refinery materials, rare",
    ["STR_ID_InnerPowerNpc[18786][Text1091]"] = "The Nemesis Tyrant in the Bloodshed Sea has the Savage Bones. You can use one to explore each time.",
    ["STR_ID_InnerPowerNpc[18786][Text1092]"] = "Sorry, you don`t have a Savage Bone.",
    ["STR_ID_InnerPowerNpc[18786][Text1093]"] = "If you don`t have a Savage Bone, you can also pay 3700 or 17.000 CPs to explore. Of course, the more you pay, the better you get.",
    ["STR_ID_InnerPowerNpc[18786][Text1094]"] = "Are you sure you want to use 3700 CPs to explored the P7 Sacred Treasures?",
    ["STR_ID_InnerPowerNpc[18786][Text1095]"] = "Are you sure you want to use 17.000 CPs to explored the P7 Sacred Treasures?",
    ["STR_ID_InnerPowerNpc[18786][Text1096]"] = "@STR_COMMON[407]",
    ["STR_ID_InnerPowerNpc[18786][Text1097]"] = "@STR_COMMON[682]",
    ["STR_ID_InnerPowerNpc[18786][Text1098]"] = "@STR_COMMON[407]",
    ["STR_ID_InnerPowerNpc[18786][Text1099]"] = "@STR_COMMON[682]",
    ["STR_ID_InnerPowerNpc[18786][Text1100]"] = "My optione its: 1: I open the  Server Captain for one YinYangSeal and you'll have 20% chance to obtain an Elemental Jade.",
    ["STR_ID_InnerPowerNpc[18786][Text1101]"] = "Sorry, you not have the YinYangSeal in your inventory.",
    ["STR_ID_InnerPowerNpc[18786][Text1102]"] = "Sorry, you not have the ElementalJade in your inventory.",
    ["STR_ID_InnerPowerNpc[18786][Text1103]"] = "I change you Stardust for Shadow Scroll , TwilightScroll or FatalScroll. Please select the item.",
    ["STR_ID_InnerPowerNpc[18786][Text1104]"] = "@STR_COMMON[710]",
    ["STR_ID_InnerPowerNpc[18786][Text1105]"] = "@STR_COMMON[710]",
    ["STR_ID_InnerPowerNpc[18786][Text1106]"] = "@STR_COMMON[710]",
    ["STR_ID_InnerPowerNpc[18786][Text1107]"] = "You'll need 4 Red Flowers and 4 White Flowers to begin the quest. You can obtain Red Flowers and White Flowers in the Evil Abyss .",
    ["STR_ID_InnerPowerNpc[18786][Text1108]"] = "If you fail to obtain key quest items during Stage 2 and Stage 3, instead you'll receive Stardust. With Stardust, you can exchange with Swapper Starry at the Infinite Abyss (27,40) for Shadow Scroll, Twilight Scroll, Fatal Scroll.",
    ["STR_ID_InnerPowerNpc[18786][Text1109]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text1110]"] = "@STR_COMMON[682]",
    ["STR_ID_InnerPowerNpc[18786][Text1111]"] = "You wasn`t very lucky today .. I hope you will have a better luck next time ^^.",
    ["STR_ID_InnerPowerNpc[18786][Text1112]"] = "Please come back when you will have at inventory 4 Red Flowers and 4 White Flowers.",
    ["STR_ID_InnerPowerNpc[18786][Text1113]"] = "@STR_COMMON[355]",
    ["STR_ID_InnerPowerNpc[18786][Text1114]"] = "@STR_COMMON[112]",
    ["STR_ID_InnerPowerNpc[18786][Text1115]"] = "@STR_COMMON[52]",
    ["STR_ID_InnerPowerNpc[18786][Text1116]"] = "I~am~NorthGeneral.~This~is~the~fourth~floor.~If~you~want~to~go~back~to~Twin~City.~I~can~help~you.",
    ["STR_ID_InnerPowerNpc[18786][Text1117]"] = "@STR_COMMON[52]",
    ["STR_ID_InnerPowerNpc[18786][Text1118]"] = "I~am~SouthGeneral.~This~is~the~third~floor~of~Labyrinth.~If~you~want~to~enter~the~next~floor,~you~should~give~me~a",
    ["STR_ID_InnerPowerNpc[18786][Text1119]"] = "~SoulToken.~Or~would~you~like~to~go~back~to~Twin~City?",
    ["STR_ID_InnerPowerNpc[18786][Text1120]"] = "@STR_COMMON[50]",
    ["STR_ID_InnerPowerNpc[18786][Text1121]"] = "You~don`t~have~a~SoulToken,~I~cannot~teleport~you~there.",
    ["STR_ID_InnerPowerNpc[18786][Text1122]"] = "Sorry,~you~don`t~have~1~SoulToken.",
    ["STR_ID_InnerPowerNpc[18786][Text1123]"] = "@STR_COMMON[52]",
    ["STR_ID_InnerPowerNpc[18786][Text1124]"] = "I~am~WestGeneral.~This~is~the~second~floor~of~Labyrinth.~If~you~want~to~enter~the~next~floor,~you~should~give~me~an",
    ["STR_ID_InnerPowerNpc[18786][Text1125]"] = "~EarthToken,~or~would~you~like~to~go~back~to~Twin~City?",
    ["STR_ID_InnerPowerNpc[18786][Text1126]"] = "@STR_COMMON[50]",
    ["STR_ID_InnerPowerNpc[18786][Text1127]"] = "@STR_COMMON[57]",
    ["STR_ID_InnerPowerNpc[18786][Text1128]"] = "@STR_COMMON[57]",
    ["STR_ID_InnerPowerNpc[18786][Text1129]"] = "@STR_COMMON[52]",
    ["STR_ID_InnerPowerNpc[18786][Text1130]"] = "I~am~EastGeneral.~This~is~the~first~floor~of~Labyrinth.~If~you~want~to~enter~the~next~floor,~you~should~give~me~a",
    ["STR_ID_InnerPowerNpc[18786][Text1131]"] = "~Sky~Token,~which~is~carried~by~the~Gold~Gosts.",
    ["STR_ID_InnerPowerNpc[18786][Text1132]"] = "@STR_COMMON[50]",
    ["STR_ID_InnerPowerNpc[18786][Text1133]"] = "@STR_COMMON[51]",
    ["STR_ID_InnerPowerNpc[18786][Text1134]"] = "@STR_COMMON[51]",
    ["STR_ID_InnerPowerNpc[18786][Text1135]"] = "@STR_COMMON[52]",
    ["STR_ID_InnerPowerNpc[18786][Text1136]"] = "Great~rewards~will~attract~many~brave~people.~I~am~looking~for~brave~people~to~help~me~take~my~patrimony~back.",
    ["STR_ID_InnerPowerNpc[18786][Text1137]"] = "@STR_COMMON[49]",
    ["STR_ID_InnerPowerNpc[18786][Text1138]"] = "You~are~kidding~on~me.~How~dare~you~come~here~to~claim~prize~with~so~few~CloudDiamonds?",
    ["STR_ID_InnerPowerNpc[18786][Text1139]"] = "@STR_COMMON[49]",
    ["STR_ID_InnerPowerNpc[18786][Text1140]"] = "You~are~kidding~on~me.~How~dare~you~come~here~to~claim~prize~with~so~few~StarDiamonds?",
    ["STR_ID_InnerPowerNpc[18786][Text1141]"] = "@STR_COMMON[49]",
    ["STR_ID_InnerPowerNpc[18786][Text1142]"] = "You~are~kidding~on~me.~How~dare~you~come~here~to~claim~prize~with~so~few~MoonDiamonds?",
    ["STR_ID_InnerPowerNpc[18786][Text1143]"] = "@STR_COMMON[49]",
    ["STR_ID_InnerPowerNpc[18786][Text1144]"] = "You~are~kidding~on~me.~How~dare~you~come~here~to~claim~prize~with~so~few~SunDiamonds?",
    ["STR_ID_InnerPowerNpc[18786][Text1145]"] = "I~need~Sun`Diamond,~Moon~Diamond,~Star~Diamond~and~Cloud~Diamond.",
    ["STR_ID_InnerPowerNpc[18786][Text1146]"] = "2~meteors~for~17~SunDiamonds,~4~meteors~for~17~MoonDiamonds,~a~normal~gem~for~17~StarDiamonds~and~a~AncestorBox",
    ["STR_ID_InnerPowerNpc[18786][Text1147]"] = "My~ancestors~built~a~Labyrinth~long~before.~Many~treasures~were~stored~there~like~SunDiamonds,~MoonDiamonds,~",
    ["STR_ID_InnerPowerNpc[18786][Text1148]"] = "The~Labyrinth~contains~4~floors~guarded~by~different~monsters.~If~you~can~find~the~treasures~and~give~them~to~me,~I~will~reward",
    ["STR_ID_InnerPowerNpc[18786][Text1149]"] = "There~are~3~kinds~of~monsters~on~each~floor.~The~more~monsters,~the~weaker~they~are.~The~ones~in~lesser",
    ["STR_ID_InnerPowerNpc[18786][Text1150]"] = "SkyToken,~EarthToken~and~SoulToken~you~need~to~enter~the~next~floor.~While~the~weak~monsters~usually~drop~treasure.",
    ["STR_ID_InnerPowerNpc[18786][Text1151]"] = "There are 3 ways to enter the Labyrinth: 1. Pay 2,000 Virtue Points; 2. Submit 5 meteors;",
    ["STR_ID_InnerPowerNpc[18786][Text1152]"] = "Sorry,~you~don`t~have~VIP.",
    ["STR_ID_InnerPowerNpc[18786][Text1153]"] = "Sorry,~you~don`t~have~enough~virtue~points.",
    ["STR_ID_InnerPowerNpc[18786][Text1154]"] = "Sorry,~you~don`t~have~5~Meteors.",
    ["STR_ID_InnerPowerNpc[18786][Text1155]"] = " Who`s there?.. Oh, you are from Twin City. aren`t you? Finally, i thoyght no one would come here to rescue us..",
    ["STR_ID_InnerPowerNpc[18786][Text1156]"] = "There is a portal on this floor (150,178). You can get to F6 from here. Be careful.",
    ["STR_ID_InnerPowerNpc[18786][Text1157]"] = "Sorry, but your have ShadowJade.",
    ["STR_ID_InnerPowerNpc[18786][Text1158]"] = "@STR_COMMON[407]",
    ["STR_ID_InnerPowerNpc[18786][Text1159]"] = " ~I guess you`ve heard about the 5th floor of Frozen Grotto before. The place is infested with so many ferocious monsters that no one dares go up there. Well, until recently,",
    ["STR_ID_InnerPowerNpc[18786][Text1160]"] = "Sorry, you not have the Grotto Key in your inventory. Go to kill monsters to obtain that key..",
    ["STR_ID_InnerPowerNpc[18786][Text1161]"] = "Sorry, but your VIP Level has to reach 4 to enter the 5th floor for free. If you want to go there, you must collect the Grotto Key.",
    ["STR_ID_InnerPowerNpc[18786][Text1162]"] = "The Frozen Grotto is a dangerous and ancient place. Many heroes have died there while searching for its hidden treasures.",
    -- {0}=Furniture.Name, {1}=Furniture.MoneyCost
    ["STR_ID_InnerPowerNpc[18786][Text1163]"] = "Do you want this {0} ? It costs only {1} silvers.",
    -- {0}=Furniture.MoneyCost
    ["STR_ID_InnerPowerNpc[18786][Text1164]"] = "You do not have {0} silvers with you.",
    ["STR_ID_InnerPowerNpc[18786][Text1165]"] = "@STR_COMMON[128]",
    ["STR_ID_InnerPowerNpc[18786][Text1166]"] = "You can deposit or withdraw your items and money, here. Wait, are you here to claim the Military Letter for the TC Vice Captain?",
    ["STR_ID_InnerPowerNpc[18786][Text1167]"] = "I am the most reliable man in Twin City! Your valuable things will be safe in my warehouse!",
    ["STR_ID_InnerPowerNpc[18786][Text1168]"] = "@STR_COMMON[711]",
    ["STR_ID_InnerPowerNpc[18786][Text1169]"] = "@STR_COMMON[711]",
    ["STR_ID_InnerPowerNpc[18786][Text1170]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text1171]"] = "You`ve got the Military Letter. Go give it to the TC Vice Captain!",
    ["STR_ID_InnerPowerNpc[18786][Text1172]"] = "This is the letter you want. Take it. By the way, don`t forget about our wonderful storage services!",
    ["STR_ID_InnerPowerNpc[18786][Text1173]"] = "@STR_COMMON[711]",
    ["STR_ID_InnerPowerNpc[18786][Text1174]"] = "In exchange of a fee of 500gold, I will teleport you back to the guild war map. Don't bother me if you are poor.",
    ["STR_ID_InnerPowerNpc[18786][Text1175]"] = "@STR_COMMON[587]",
    ["STR_ID_InnerPowerNpc[18786][Text1176]"] = "Are~you~heading~for~the~next~teleporter?~It~is~free~for~our~members,~and~1,000~silver~for~others.",
    ["STR_ID_InnerPowerNpc[18786][Text1177]"] = "Please~take~1000~silvers~to~use~guild~teleporter.",
    ["STR_ID_InnerPowerNpc[18786][Text1178]"] = "A~Teleporter~costs~100,000~silver.~After~you~buy~one~and~place~it~at~a~good~location,~you~can~be~teleported~there~directly.",
