    ["STR_ID_InnerPowerNpc[18786][Text1247]"] = "You must have heard that the Olympic Games. I`ve been waiting for it for my entire life. There are 10 Flame Stones",
    ["STR_ID_InnerPowerNpc[18786][Text1248]"] = "You cannot claim experience while guild war.",
    ["STR_ID_InnerPowerNpc[18786][Text1249]"] = "You cannot claim experience if you don't have a rune.",
    ["STR_ID_InnerPowerNpc[18786][Text1250]"] = "@STR_COMMON[128]",
    ["STR_ID_InnerPowerNpc[18786][Text1251]"] = "You already have a rune.",
    ["STR_ID_InnerPowerNpc[18786][Text1252]"] = "You? Wait a sec... Oh, yeah, no wonder you looked familir. Each player can carry this quest ONCE a week",
    ["STR_ID_InnerPowerNpc[18786][Text1253]"] = "Ah, you seem very interested! Good. You are eligible to light up the flame! But, it`s not the right time. You see, the",
    ["STR_ID_InnerPowerNpc[18786][Text1254]"] = "Yeah. I`ve prepare 10 Flame Stones in the Wind Plain and Guild Arena. When the time comes, I will give you a Jade Rune. You",
    ["STR_ID_InnerPowerNpc[18786][Text1255]"] = "Welcome, this is the Class 6 model house with many new features. When you`re walking around the house,",
    ["STR_ID_InnerPowerNpc[18786][Text1256]"] = "There are two ways to upgrade to Class 6: pay 8,999 CPs or submit 500 Class 6 House Packs. You can collect the Class 6 House Packs",
    ["STR_ID_InnerPowerNpc[18786][Text1257]"] = "We need totally 500 Class 6 House Packs to upgrade your house to Class 6. So, how many packs would you like to submit this time?",
    ["STR_ID_InnerPowerNpc[18786][Text1258]"] = "@STR_COMMON[720]",
    ["STR_ID_InnerPowerNpc[18786][Text1259]"] = "@STR_COMMON[721]",
    ["STR_ID_InnerPowerNpc[18786][Text1260]"] = "You have failed to upgrade the house to level 6 , give a try again later maybe you will have more luck .",
    ["STR_ID_InnerPowerNpc[18786][Text1261]"] = "@STR_COMMON[722]",
    ["STR_ID_InnerPowerNpc[18786][Text1262]"] = "@STR_COMMON[720]",
    ["STR_ID_InnerPowerNpc[18786][Text1263]"] = "@STR_COMMON[721]",
