    ["STR_ID_InnerPowerNpc[18786][Text1266]"] = "@STR_COMMON[721]",
    ["STR_ID_InnerPowerNpc[18786][Text1267]"] = "Sorry, I can`t help you in this matter since you don`t have enough CPs. Please bring the money, next time.",
    ["STR_ID_InnerPowerNpc[18786][Text1268]"] = "@STR_COMMON[12]",
