    ["STR_ID_InnerPowerNpc[18786][Text1528]"] = "@STR_COMMON[126]",
    ["STR_ID_InnerPowerNpc[18786][Text1529]"] = "@STR_COMMON[127]",
    ["STR_ID_InnerPowerNpc[18786][Text1530]"] = "Hunting~and~mining~for~the~treasure~is~an~exciting~thing.~However,~they~also~pile~up~in~your~inventories.",
    ["STR_ID_InnerPowerNpc[18786][Text1531]"] = "10 DragonBall can be packed into a DragonBall Pack. Would you like me to pack them for you?",
    ["STR_ID_InnerPowerNpc[18786][Text1532]"] = "Sorry, you don`t have 10 DragonBall.",
    ["STR_ID_InnerPowerNpc[18786][Text1533]"] = "10 Meteors can be packed into a Meteor Pack. Would you like me to pack them for you?",
    ["STR_ID_InnerPowerNpc[18786][Text1534]"] = "Sorry, you don`t have 10 meteors.",
    ["STR_ID_InnerPowerNpc[18786][Text1535]"] = "Pay 100,000 Silver and give me 5 EXP Balls, I can pack them into an EXP Ball Gift Box for you!",
    ["STR_ID_InnerPowerNpc[18786][Text1536]"] = "@STR_COMMON[331]",
    ["STR_ID_InnerPowerNpc[18786][Text1537]"] = "@STR_COMMON[331]",
    ["STR_ID_InnerPowerNpc[18786][Text1538]"] = "Sorry, you don`t have 5 EXP Balls.",
