    ["STR_ID_InnerPowerNpc[18786][Text1566]"] = "Sorry, you don`t have 5 +1 Stones.",
    ["STR_ID_InnerPowerNpc[18786][Text1567]"] = "The Dragon Ball is really a precious item. You can use it to refine equipment. What`s more, if you use it properly,",
    ["STR_ID_InnerPowerNpc[18786][Text1568]"] = "According to your ability, I can help you gain EXP from 1 Dragon Ball, each day.",
    ["STR_ID_InnerPowerNpc[18786][Text1569]"] = "Sorry, but you have a big level.",
    ["STR_ID_InnerPowerNpc[18786][Text1570]"] = "Sorry, but you my service today, come back tomorow with one dragonball.",
    ["STR_ID_InnerPowerNpc[18786][Text1571]"] = "Sorry, but you don`t have enough Dragon Balls.",
    ["STR_ID_InnerPowerNpc[18786][Text1572]"] = "@STR_COMMON[87]",
    ["STR_ID_InnerPowerNpc[18786][Text1573]"] = "@STR_COMMON[88]",
    ["STR_ID_InnerPowerNpc[18786][Text1574]"] = "@STR_COMMON[89]",
    ["STR_ID_InnerPowerNpc[18786][Text1575]"] = "@STR_COMMON[88]",
    ["STR_ID_InnerPowerNpc[18786][Text1576]"] = "@STR_COMMON[89]",
    ["STR_ID_InnerPowerNpc[18786][Text1577]"] = "@STR_COMMON[88]",
    ["STR_ID_InnerPowerNpc[18786][Text1578]"] = "@STR_COMMON[89]",
    ["STR_ID_InnerPowerNpc[18786][Text1579]"] = "@STR_COMMON[87]",
    ["STR_ID_InnerPowerNpc[18786][Text1580]"] = "@STR_COMMON[88]",
    ["STR_ID_InnerPowerNpc[18786][Text1581]"] = "@STR_COMMON[89]",
    ["STR_ID_InnerPowerNpc[18786][Text1582]"] = "@STR_COMMON[88]",
    ["STR_ID_InnerPowerNpc[18786][Text1583]"] = "@STR_COMMON[89]",
    ["STR_ID_InnerPowerNpc[18786][Text1584]"] = "@STR_COMMON[88]",
    ["STR_ID_InnerPowerNpc[18786][Text1585]"] = "@STR_COMMON[89]",
    ["STR_ID_InnerPowerNpc[18786][Text1586]"] = "Look!~Here~is~the~LuckyBox,~a~kind~of~magical~box~which~makes~your~dream~come~true.",
    ["STR_ID_InnerPowerNpc[18786][Text1587]"] = "You~have~chance~to~get~whatever~you~desire~from~a~LuckyBox.~It~May~be~a~Dragonball,~+8~weapon,~or",
    ["STR_ID_InnerPowerNpc[18786][Text1588]"] = "@STR_COMMON[45]",
    ["STR_ID_InnerPowerNpc[18786][Text1589]"] = "@STR_COMMON[45]",
    ["STR_ID_InnerPowerNpc[18786][Text1590]"] = "Each player can draw from the Lottery up to 10 times, each day. But if you are a VIP, you will have extra chances to play! Level 1 VIP: 10 extra chances. Level 2 VIP: 20 extra chances. Level 3 VIP: 30 extra chances. Level 4 VIP: 40 extra chances. Level 5 VIP: 50 extra chances. Level 6 VIP: 60 extra chances.",
    ["STR_ID_InnerPowerNpc[18786][Text1591]"] = "You don`t have any Lottery Tickets to exchange for the Small Lottery Tickets.",
    ["STR_ID_InnerPowerNpc[18786][Text1592]"] = "Sorry, you don`t have enough Lottery Tickets. You can exchange the tickets one by one, or find me again when you have 5 Lottery Tickets.",
    ["STR_ID_InnerPowerNpc[18786][Text1593]"] = "How many Lottery Tickets would you like to exchange?",
    ["STR_ID_InnerPowerNpc[18786][Text1594]"] = "There are many Lucky Boxes in the Lottery Center. Pay 3 Small Lottery Tickets, and you can draw from the Lucky Box! If you are not satisfied with the item you get, you can pay 1 more Small Lottery Ticket to change the item you drew. However, you can",
    ["STR_ID_InnerPowerNpc[18786][Text1595]"] = "I devote all my life to the research of eternity. And finally I know the secret of rebirth! Well, anything I can help you with?",
    ["STR_ID_InnerPowerNpc[18786][Text1596]"] = "Reborn~level~70+~players~can~redistribute~their~attribute~points~at~the~cost~of~a~dragonball.",
    ["STR_ID_InnerPowerNpc[18786][Text1597]"] = "@STR_COMMON[492]",
    ["STR_ID_InnerPowerNpc[18786][Text1598]"] = "@STR_COMMON[91]",
    ["STR_ID_InnerPowerNpc[18786][Text1599]"] = "@STR_COMMON[92]",
    ["STR_ID_InnerPowerNpc[18786][Text1600]"] = "From now on, have total control of your life! If you've been Reborn twice and are at least Level 110, just bring me some Oblivion Dew and I'll help you become Reincarnated! After the Reincarnation, your class skills will revert to level 0,",
    ["STR_ID_InnerPowerNpc[18786][Text1601]"] = "Oblivion Dew is available in the Honor Store and the Horse Race Store. You can use your Honor Points or Horse Race Points to purchase one.",
    ["STR_ID_InnerPowerNpc[18786][Text1602]"] = "You have not been Reborn twice. I`m afraid you will not withstand the power of the Oblivion Dew. Come to me when you get stronger.",
    ["STR_ID_InnerPowerNpc[18786][Text1603]"] = "There are two kinds of reborns. One is the normal one and the second one is blessed.",
    ["STR_ID_InnerPowerNpc[18786][Text1604]"] = "Sorry, you don't have CelestialStone.",
    ["STR_ID_InnerPowerNpc[18786][Text1605]"] = "You~haven`t~reached~the~highest~rank~yet.~Please~work~harder. You cannot reborn if your level is not 110+ for water saints and 120+ for other masters.",
    ["STR_ID_InnerPowerNpc[18786][Text1606]"] = "You don't worry, it's not gonna hurt you a bit when getting the third life. You just need an exemption token and it's all going to be fine.",
    ["STR_ID_InnerPowerNpc[18786][Text1607]"] = "@STR_COMMON[493]",
    ["STR_ID_InnerPowerNpc[18786][Text1608]"] = "Sorry,~you~are~ineligible~for~second~rebirth.~Please~wait~until~you~are~a~level~120~reborn~person.",
    ["STR_ID_InnerPowerNpc[18786][Text1609]"] = "Select the super gem you desire.",
    ["STR_ID_InnerPowerNpc[18786][Text1610]"] = "@STR_COMMON[494]",
    ["STR_ID_InnerPowerNpc[18786][Text1611]"] = "@STR_COMMON[494]",
    ["STR_ID_InnerPowerNpc[18786][Text1612]"] = "Sorry, but you need atleast 5 free spaces in your inventory.",
    ["STR_ID_InnerPowerNpc[18786][Text1613]"] = "Sorry, you don't have CelatialStone.",
    ["STR_ID_InnerPowerNpc[18786][Text1614]"] = "@STR_COMMON[493]",
    ["STR_ID_InnerPowerNpc[18786][Text1615]"] = "Wow, it seems that I need to get some more steeds for all of you guys to choose! Maybe I`ll be a millionaire. It`s just a",
    ["STR_ID_InnerPowerNpc[18786][Text1616]"] = "There are a few kinds of steeds here, with many more that you can get. A good steed is a pretty convenient thing to have.",
    ["STR_ID_InnerPowerNpc[18786][Text1617]"] = "You can unite 2 mounts with different appearances to breed a new mount. In this way, you can also improve on your steed`s",
    ["STR_ID_InnerPowerNpc[18786][Text1618]"] = "Hey! Guys, look at me! Good Steeds! Nah, not me. I mean there are some good steeds for you to choose. Would you like to take a",
    ["STR_ID_InnerPowerNpc[18786][Text1619]"] = "@STR_COMMON[349]",
    ["STR_ID_InnerPowerNpc[18786][Text1620]"] = "A good steed can increase your movement and efficiency. Why not pay a visit to the",
    ["STR_ID_InnerPowerNpc[18786][Text1621]"] = "Pay~a~visit~to~the~Mount~Retailer.",
    ["STR_ID_InnerPowerNpc[18786][Text1622]"] = "@STR_COMMON[349]",
    ["STR_ID_InnerPowerNpc[18786][Text1623]"] = "It`s upgradable. You`ll need to equip a two-handed weapon and be mounted to use this skill. You will attack a target area within 15 paces and cause",
    ["STR_ID_InnerPowerNpc[18786][Text1624]"] = "Sorry, but you`ll need to reach Level 30, first.",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1625]"] = "@STR_COMMON[32]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1626]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text1627]"] = "You don`t have 500,000 silver. You are unable to learn the ChargingVortex skill.",
    ["STR_ID_InnerPowerNpc[18786][Text1628]"] = "After you equip and ride your mount, you can right click the War Cry skill to dismount the players in a certain area whose",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1629]"] = "@STR_COMMON[32]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1630]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text1631]"] = "You don`t have 1,000,000 silver. You are unable to learn the war cry skill.",
    ["STR_ID_InnerPowerNpc[18786][Text1632]"] = "After you equip and ride your mount, you can right click the Spook skill to dismount a player whose mount`s Lineage Level is",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1633]"] = "@STR_COMMON[32]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1634]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text1635]"] = "You don`t have 100,000 silver. You are unable to learn the Spook skill.",
    ["STR_ID_InnerPowerNpc[18786][Text1636]"] = "After the mount is equipped, you can right click the (Riding) button or drag the button into the shortcut column to ride",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1637]"] = "@STR_COMMON[32]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1638]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text1639]"] = "You don`t have 50,000 silver. You are unable to learn the Riding skill.",
    ["STR_ID_InnerPowerNpc[18786][Text1640]"] = "Sorry, but you are not a Taoist.",
    ["STR_ID_InnerPowerNpc[18786][Text1641]"] = "@STR_COMMON[571]",
    ["STR_ID_InnerPowerNpc[18786][Text1642]"] = "@STR_COMMON[571]",
    ["STR_ID_InnerPowerNpc[18786][Text1643]"] = "@STR_COMMON[571]",
    ["STR_ID_InnerPowerNpc[18786][Text1644]"] = "You've gained your missing skills.",
    ["STR_ID_InnerPowerNpc[18786][Text1645]"] = "You don't have any skills that need to be reclaimed.",
    ["STR_ID_InnerPowerNpc[18786][Text1646]"] = "@STR_COMMON[323]",
    ["STR_ID_InnerPowerNpc[18786][Text1647]"] = "@STR_COMMON[327]",
    ["STR_ID_InnerPowerNpc[18786][Text1648]"] = "Ah, you look promising. I bet Taoist will be a big name in a short time. Listen, you can learn class skills and",
    ["STR_ID_InnerPowerNpc[18786][Text1649]"] = "@STR_COMMON[21]",
    ["STR_ID_InnerPowerNpc[18786][Text1650]"] = "The Great Sun King has acquired the essence of Taoism and mad a Divine Panacea.",
    ["STR_ID_InnerPowerNpc[18786][Text1651]"] = "@STR_COMMON[461]",
    ["STR_ID_InnerPowerNpc[18786][Text1652]"] = "@STR_COMMON[24]",
    ["STR_ID_InnerPowerNpc[18786][Text1653]"] = "@STR_COMMON[25]",
    ["STR_ID_InnerPowerNpc[18786][Text1654]"] = "@STR_COMMON[572]",
    ["STR_ID_InnerPowerNpc[18786][Text1655]"] = "@STR_COMMON[27]",
    ["STR_ID_InnerPowerNpc[18786][Text1656]"] = "@STR_COMMON[28]",
    ["STR_ID_InnerPowerNpc[18786][Text1657]"] = "@STR_COMMON[572]",
    ["STR_ID_InnerPowerNpc[18786][Text1658]"] = "@STR_COMMON[29]",
    ["STR_ID_InnerPowerNpc[18786][Text1659]"] = "@STR_COMMON[30]",
    ["STR_ID_InnerPowerNpc[18786][Text1660]"] = "@STR_COMMON[572]",
    ["STR_ID_InnerPowerNpc[18786][Text1661]"] = "@STR_COMMON[31]",
    ["STR_ID_InnerPowerNpc[18786][Text1662]"] = "Only Pure Fire Taoists, who have trained as Water Taoists for all 3 lives, can learn the Pure Skills, Azure Shield. If you`ve been Reborn twice, but are not a Pure Fire Taoist, you can take some",
    ["STR_ID_InnerPowerNpc[18786][Text1663]"] = "Only Pure Fire Taoists, who have trained as Fire Taoists for all 3 lives, can learn the Pure Skills, Heaven Blade. If you`ve been Reborn twice, but are not a Pure Fire Taoist, you can take some",
