    ["STR_ID_InnerPowerNpc[18786][Text1931]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text1932]"] = "Ah, you look promising. I bet `Warrior` will be a big name in a short time. Listen, you can learn class skills and",
    ["STR_ID_InnerPowerNpc[18786][Text1933]"] = "@STR_COMMON[21]",
