    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1977]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text1978]"] = "I`m proud that you made a mature decision! The warriors are adept in the use of weapons and shields for additional defense. Do you want to get promoted, now?",
    ["STR_ID_InnerPowerNpc[18786][Text1979]"] = "You`ve learned ways of the Warrior. Now, more weapons and armors are available for you, while new skills are at your disposal. Go test your power!",
    ["STR_ID_InnerPowerNpc[18786][Text1980]"] = "You don`t look like a Windwalker. What`s the matter? If you were ever a Windwalker in either of the previous two lives, you can learn [Frost Gaze I] from me.",
    ["STR_ID_InnerPowerNpc[18786][Text1981]"] = "@STR_COMMON[726]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1982]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text1983]"] = "@STR_COMMON[726]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1984]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text1985]"] = "@STR_COMMON[726]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1986]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text1987]"] = "Hey, FellowBrother! You`re back. Are you okay? No hurry, the Chief has sent me a letter and told me the things.",
    ["STR_ID_InnerPowerNpc[18786][Text1988]"] = "Our Windwalker school was founded by Saint Wan on the principle of KINDNESS and JUSTICE. Once you decide to",
    ["STR_ID_InnerPowerNpc[18786][Text1989]"] = "~join us as a Windwalker, you take the responsibility for the security of the country against alien invaders and devils.",
    ["STR_ID_InnerPowerNpc[18786][Text1990]"] = "Our school and the devil force have been at daggers drawn for centuries, but I don`t really get their purposes for",
    ["STR_ID_InnerPowerNpc[18786][Text1991]"] = "~attacking us and intruding the imperial mausoleum this time. Now that we`ve completed the service in the mausoleum,",
    ["STR_ID_InnerPowerNpc[18786][Text1992]"] = "~we should return to society. FellowBrother, set off to investigate and avenge the deaths of our fellows!",
    ["STR_ID_InnerPowerNpc[18786][Text1993]"] = "You`re such a talent and so promising. The Windwalker shool will amaze the world soon.",
    ["STR_ID_InnerPowerNpc[18786][Text1994]"] = "~Remember, you can learn class skills and get promoted here to start your life. Would you like",
    ["STR_ID_InnerPowerNpc[18786][Text1995]"] = "~to learn something about your class promotion and quests?",
    ["STR_ID_InnerPowerNpc[18786][Text1996]"] = "Congratulations! You`ve graduated from the training quest. From now on, you are no longer a simple recruit, but a trained",
    ["STR_ID_InnerPowerNpc[18786][Text1997]"] = "~soldier. You can sign up for your class quests with me when you`re Level 12, and get promoted at Level 15.",
    ["STR_ID_InnerPowerNpc[18786][Text1998]"] = "~The world is filled with dangers, so be sure and take care of yourself!",
    ["STR_ID_InnerPowerNpc[18786][Text1999]"] = "The TC Vice Captain (TwinCity 384,251) is now damned busy. Hey, if you can give him a hand,",
    ["STR_ID_InnerPowerNpc[18786][Text2000]"] = "~he will remember you for the rest of his life. Hah, just kidding. Anyway, would you like to help him?",
    ["STR_ID_InnerPowerNpc[18786][Text2001]"] = "FellowBrother, you`re not qualified to be [WindwalkerGuard]. You should reach Level 15 to get promoted.",
    ["STR_ID_InnerPowerNpc[18786][Text2002]"] = "@STR_COMMON[727]",
    ["STR_ID_InnerPowerNpc[18786][Text2003]"] = "FellowBrother, you`re not qualified to be [WindwalkerGuard]. You should reach Level 40 to get promoted.",
    ["STR_ID_InnerPowerNpc[18786][Text2004]"] = "@STR_COMMON[26]",
    ["STR_ID_InnerPowerNpc[18786][Text2005]"] = "@STR_COMMON[727]",
    ["STR_ID_InnerPowerNpc[18786][Text2006]"] = "FellowBrother, you`re not qualified to be [WindwalkerGuard]. You should reach Level 70 to get promoted.",
    ["STR_ID_InnerPowerNpc[18786][Text2007]"] = "@STR_COMMON[25]",
    ["STR_ID_InnerPowerNpc[18786][Text2008]"] = "@STR_COMMON[26]",
    ["STR_ID_InnerPowerNpc[18786][Text2009]"] = "@STR_COMMON[727]",
    ["STR_ID_InnerPowerNpc[18786][Text2010]"] = "FellowBrother, you`re not qualified to be [WindwalkerGuard]. You should reach Level 100 to get promoted.",
    ["STR_ID_InnerPowerNpc[18786][Text2011]"] = "@STR_COMMON[28]",
    ["STR_ID_InnerPowerNpc[18786][Text2012]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text2013]"] = "@STR_COMMON[727]",
    ["STR_ID_InnerPowerNpc[18786][Text2014]"] = "FellowBrother, you`re not qualified to be [WindwalkerGuard]. You should reach Level 110 to get promoted.",
    ["STR_ID_InnerPowerNpc[18786][Text2015]"] = "@STR_COMMON[30]",
    ["STR_ID_InnerPowerNpc[18786][Text2016]"] = "@STR_COMMON[14]",
    ["STR_ID_InnerPowerNpc[18786][Text2017]"] = "@STR_COMMON[727]",
    ["STR_ID_InnerPowerNpc[18786][Text2018]"] = "@STR_COMMON[31]",
    ["STR_ID_InnerPowerNpc[18786][Text2019]"] = "Our Windwalker school is divided into two branches: Chaser and Stomper. Chaser focuses on",
    ["STR_ID_InnerPowerNpc[18786][Text2020]"] = "~ranged combat, while Stomper excels in melee combat. I`m here representing the Chief to",
    ["STR_ID_InnerPowerNpc[18786][Text2021]"] = "~impart distinctive skills to the Windwalkers.",
    ["STR_ID_InnerPowerNpc[18786][Text2022]"] = "Frost Gaze is an exclusive rebirth skill for Windwalker. The heroes who got reborn to be Windwalker can learn Frost Gaze I. If both of your precious andd",
    ["STR_ID_InnerPowerNpc[18786][Text2023]"] = "~current Class are Windwalker, you can learn Frost Gaze II. While for Windwalkers who were also a Windwalker in previous two lives, they can learn Frost Gaze III.",
    ["STR_ID_InnerPowerNpc[18786][Text2024]"] = "@STR_COMMON[726]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text2025]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text2026]"] = "@STR_COMMON[726]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text2027]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text2028]"] = "@STR_COMMON[726]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text2029]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text2030]"] = "Omnipotence and Justice Chant are basic skills for Windwalker, which are available to both Chaser and Stomper learners. I`ll teach you if you want.",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text2031]"] = "@STR_COMMON[728]",
    ["STR_ID_InnerPowerNpc[18786][Text2032]"] = "@STR_COMMON[726]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text2033]"] = "@STR_COMMON[33]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text2034]"] = "@STR_COMMON[728]",
    ["STR_ID_InnerPowerNpc[18786][Text2035]"] = "@STR_COMMON[726]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text2036]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text2037]"] = "The Chaser branch is famous for its ability to control wind and outstanding ranged attacks.",
    ["STR_ID_InnerPowerNpc[18786][Text2038]"] = "@STR_COMMON[729]",
