    ["STR_ID_InnerPowerNpc[18786][Text2120]"] = "@STR_COMMON[32]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text2121]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text2122]"] = "300 years ago, General Pak was ordered to fight against the Flame Devastator. However, a traitor in his army led to Pak`s unexpected death.",
