    ["STR_ID_InnerPowerNpc[18786][Text2351]"] = "@STR_COMMON[32]",
    ["STR_ID_InnerPowerNpc[18786][Text2352]"] = "Sorry, but you are not a Pirate.",
    ["STR_ID_InnerPowerNpc[18786][Text2353]"] = "@STR_COMMON[496]",
    ["STR_ID_InnerPowerNpc[18786][Text2354]"] = "@STR_COMMON[496]",
    ["STR_ID_InnerPowerNpc[18786][Text2355]"] = "@STR_COMMON[496]",
    ["STR_ID_InnerPowerNpc[18786][Text2356]"] = "Ah, you look promising. I bet `Pirate` will be a big name in a short time. Listen, you can learn class skills and",
    ["STR_ID_InnerPowerNpc[18786][Text2357]"] = "@STR_COMMON[21]",
    ["STR_ID_InnerPowerNpc[18786][Text2358]"] = "As a Pirate, you`ll need to reach Level 40 to get promoted to a Pirate Gunner. You will learn Adrenaline Rush, Eagle Eye, Blackbeard`s Rage and Black Spot after promotion.",
    ["STR_ID_InnerPowerNpc[18786][Text2359]"] = "@STR_COMMON[22]",
    ["STR_ID_InnerPowerNpc[18786][Text2360]"] = "@STR_COMMON[497]",
