    ["STR_ID_InnerPowerNpc[18786][Text2370]"] = "@STR_COMMON[31]",
    ["STR_ID_InnerPowerNpc[18786][Text2371]"] = "If you want to learn the Scurvy Bomb, you`ll need to be a pure Pirate, who`ve been a Pirate for 3 straight lives. You can talk to the Rebirth Master in the Market to have the Reincarnation.",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text2372]"] = "@STR_COMMON[32]",
    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text2373]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text2374]"] = "If you want to learn the Scurvy Bomb, you`ll need to be a pure Pirate, who`ve been a Pirate for 3 straight lives.",
    ["STR_ID_InnerPowerNpc[18786][Text2375]"] = "As an Intern Pirate, you can get promoted to a Pirate and learn Blade Tempest after you reach Level 15. When you reach Level 20, you can learn Gale Bomb.",
    ["STR_ID_InnerPowerNpc[18786][Text2376]"] = "@STR_COMMON[498]",
