    ["STR_ID_InnerPowerNpc[18786][Text2378]"] = "@STR_COMMON[500]",
    ["STR_ID_InnerPowerNpc[18786][Text2379]"] = "It`s said Pirate`s Epic skills contains the mighty power of sea which can devastate all things on the earth.\n",
