    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text2423]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text2424]"] = "Sorry you are not reborn, or not is pirat-pirat ",
    ["STR_ID_InnerPowerNpc[18786][Text2425]"] = "Well, the Jiang Hu is quite chaotic. I`ll test your understanding with several questions. If you pass, you`re able to name a skill of your own and start your adventure as a Jiang Hu warrior!",
    ["STR_ID_InnerPowerNpc[18786][Text2426]"] = "Sorry, you not have 2nd Reborn, or you are learning Jiang Hu,",
    ["STR_ID_InnerPowerNpc[18786][Text2427]"] = "Being a fighter of the Jiang Hu, you can train your Inner-strength after activating `Jiang` button at the character window. Each time you study will cost you 10 Study Points",
    ["STR_ID_InnerPowerNpc[18786][Text2428]"] = "You need to activate the `Jiang` mode, and defeat a player whose Talent Status is not lower than yours to raise your Status Level by 1,",
    ["STR_ID_InnerPowerNpc[18786][Text2429]"] = "Jiang Hu fighters will gain up to 100 Free Courses by accumulating the Talent Points over time, whether online or not. The higher the Talent Status,",
    ["STR_ID_InnerPowerNpc[18786][Text2430]"] = "If you want to leave the Jiang Hu for a while, deactivate the `Jiang` mode and wait for 10 minutes to quit.",
    ["STR_ID_InnerPowerNpc[18786][Text2431]"] = "The Clan is not only a group, but also a bond between its members! You can have a maximum of 12 members in a clan at one time,",
    -- {0}=(byte)(client.Player.MyClan.Level + 1)
    ["STR_ID_InnerPowerNpc[18786][Text2432]"] = "Your current Clan Level is Level {0}",
    -- {0}=Role.Instance.Clan.UpdateLevelAmount[client.Player.MyClan.Level]
    ["STR_ID_InnerPowerNpc[18786][Text2433]"] = "~You need {0} Silver`s in the Clan Fund to upgrade the Clan Level.",
    -- {0}=client.Player.MyClan.BP
    ["STR_ID_InnerPowerNpc[18786][Text2434]"] = "~You can gain BP Bonus Level {0} now: The members can share percent of the Battle Power margin between themselves and",
    -- {0}=client.Player.MyClan.BP
    ["STR_ID_InnerPowerNpc[18786][Text2435]"] = "~the highest Battle Power team member in the same map at BP Bonus Level {0}.",
    ["STR_ID_InnerPowerNpc[18786][Text2436]"] = "Only~the~Clan~Leader~can~change~the~Guild`s~name,~which~will~take~effect~after~the~server~maintenance~on~the~second~day.~It`ll~cost~you~1075~CPs.~Deal?",
    ["STR_ID_InnerPowerNpc[18786][Text2437]"] = "Please~enter~a~new~name~for~your~Clan.",
    ["STR_ID_InnerPowerNpc[18786][Text2438]"] = "@STR_COMMON[333]",
    ["STR_ID_InnerPowerNpc[18786][Text2439]"] = "@STR_COMMON[334]",
    ["STR_ID_InnerPowerNpc[18786][Text2440]"] = "Sorry,~you`re~not~the~Clan~Leader.",
    ["STR_ID_InnerPowerNpc[18786][Text2441]"] = "Only the Clan Leader has the right to disband the Clan. Do you really want to disband your Clan?",
    ["STR_ID_InnerPowerNpc[18786][Text2442]"] = "@STR_COMMON[335]",
    ["STR_ID_InnerPowerNpc[18786][Text2443]"] = "@STR_COMMON[335]",
    -- {0}=client.Player.MyClan.BP
    ["STR_ID_InnerPowerNpc[18786][Text2444]"] = "@STR_COMMON[336]",
    -- {0}=Role.Instance.Clan.UpdateBPAmount[client.Player.MyClan.BP]
    ["STR_ID_InnerPowerNpc[18786][Text2445]"] = "@STR_COMMON[337]",
    ["STR_ID_InnerPowerNpc[18786][Text2446]"] = "@STR_COMMON[338]",
    ["STR_ID_InnerPowerNpc[18786][Text2447]"] = "@STR_COMMON[339]",
    ["STR_ID_InnerPowerNpc[18786][Text2448]"] = "@STR_COMMON[340]",
    -- {0}=client.Player.MyClan.BP
    ["STR_ID_InnerPowerNpc[18786][Text2449]"] = "@STR_COMMON[336]",
    -- {0}=Role.Instance.Clan.UpdateBPAmount[client.Player.MyClan.BP]
    ["STR_ID_InnerPowerNpc[18786][Text2450]"] = "@STR_COMMON[337]",
    ["STR_ID_InnerPowerNpc[18786][Text2451]"] = "@STR_COMMON[338]",
    -- {0}=Money
    ["STR_ID_InnerPowerNpc[18786][Text2452]"] = "Oh, you don`t have {0} in Clan Fund to gain the BP Bonus Level... Maybe I will help you next time when you have the",
    ["STR_ID_InnerPowerNpc[18786][Text2453]"] = "~money.",
    ["STR_ID_InnerPowerNpc[18786][Text2454]"] = "@STR_COMMON[339]",
    ["STR_ID_InnerPowerNpc[18786][Text2455]"] = "@STR_COMMON[340]",
    -- {0}=(byte)(client.Player.MyClan.Level + 1), {1}=Role.Instance.Clan.UpdateLevelAmount[client.Player.MyClan.Level]
    ["STR_ID_InnerPowerNpc[18786][Text2456]"] = "@STR_COMMON[341]",
    ["STR_ID_InnerPowerNpc[18786][Text2457]"] = "@STR_COMMON[338]",
    ["STR_ID_InnerPowerNpc[18786][Text2458]"] = "@STR_COMMON[342]",
    -- {0}=(byte)(client.Player.MyClan.Level + 1), {1}=Role.Instance.Clan.UpdateLevelAmount[client.Player.MyClan.Level]
    ["STR_ID_InnerPowerNpc[18786][Text2459]"] = "@STR_COMMON[341]",
    ["STR_ID_InnerPowerNpc[18786][Text2460]"] = "@STR_COMMON[338]",
    -- {0}=Money
    ["STR_ID_InnerPowerNpc[18786][Text2461]"] = "Your do not have {0} silvers in you Clan.",
    ["STR_ID_InnerPowerNpc[18786][Text2462]"] = "@STR_COMMON[342]",
    ["STR_ID_InnerPowerNpc[18786][Text2463]"] = "After you reach Level 50, you can create a Clan with 500,000 silver, half of which will be the Clan Fund. You can recruit your",
    ["STR_ID_InnerPowerNpc[18786][Text2464]"] = "To create a Clan, you need to think of a fabulous name for it! Type in the name you like, but remember the name should be",
    ["STR_ID_InnerPowerNpc[18786][Text2465]"] = "~less than 35 characters. A name is very important to your reputation. You should make it good enough so that people will",
    ["STR_ID_InnerPowerNpc[18786][Text2466]"] = "~tremble upon the very mention of it! So what`ll it be?",
    ["STR_ID_InnerPowerNpc[18786][Text2467]"] = "You haven`t reached Level 50 and are unable to create a Clan. You should be strong enough to lead your Clan!",
    ["STR_ID_InnerPowerNpc[18786][Text2468]"] = "You don`t have enough money to create a Clan. Creating a Clan needs 500,000 silver. Half of which will be the Clan Fund.",
    ["STR_ID_InnerPowerNpc[18786][Text2469]"] = "@STR_COMMON[343]",
    ["STR_ID_InnerPowerNpc[18786][Text2470]"] = "Congratulations! You have created a Clan successfully! You should protect your Clan and fight with your Clan members for glory",
    ["STR_ID_InnerPowerNpc[18786][Text2471]"] = "~and honor!",
    ["STR_ID_InnerPowerNpc[18786][Text2472]"] = "@STR_COMMON[343]",
    ["STR_ID_InnerPowerNpc[18786][Text2473]"] = "Now you can sign up at the Clan Guide in the name of your Clan to join in the Clan War once a day. You will obtain a Normal",
    ["STR_ID_InnerPowerNpc[18786][Text2474]"] = "~Clan Pack as a reward if you win!",
    ["STR_ID_InnerPowerNpc[18786][Text2475]"] = "If you can occupy the map continuously, you will get better prizes! Besides the reward you get after you win the Clan War,",
    ["STR_ID_InnerPowerNpc[18786][Text2476]"] = "~you will get a Refined Clan Pack on the 7th day, Unique Clan Pack on the 14th day, Elite Clan Pack on the 21st day, and a",
    ["STR_ID_InnerPowerNpc[18786][Text2477]"] = "~Super Clan Pack on the 28th day! The stronger you are, the more you can win!",
    ["STR_ID_InnerPowerNpc[18786][Text2478]"] = "Greetings! I am the guild director, in charge of administrating and managing guilds. What business do you have with me?",
    ["STR_ID_InnerPowerNpc[18786][Text2479]"] = "Only~the~Guild~Leader~can~change~the~Guild`s~name,~which~will~take~effect~after~the~server~maintenance~on~the~second~day.~It`ll~cost~you~1075~CPs.~Deal?",
    ["STR_ID_InnerPowerNpc[18786][Text2480]"] = "Please~enter~a~new~name~for~your~Guild.",
    ["STR_ID_InnerPowerNpc[18786][Text2481]"] = "@STR_COMMON[333]",
    ["STR_ID_InnerPowerNpc[18786][Text2482]"] = "@STR_COMMON[334]",
    ["STR_ID_InnerPowerNpc[18786][Text2483]"] = "Sorry,~you`re~not~the~Guild~Leader.",
    ["STR_ID_InnerPowerNpc[18786][Text2484]"] = "A great war wich involves milHarley of heroes is about the fire. If you have a Level 9+",
    ["STR_ID_InnerPowerNpc[18786][Text2485]"] = "@STR_COMMON[594]",
    ["STR_ID_InnerPowerNpc[18786][Text2486]"] = "@STR_COMMON[594]",
    ["STR_ID_InnerPowerNpc[18786][Text2487]"] = "Write the name, you wana use for guild",
    ["STR_ID_InnerPowerNpc[18786][Text2488]"] = "Sorry you are not the Guild Leader.",
    ["STR_ID_InnerPowerNpc[18786][Text2489]"] = "@STR_COMMON[595]",
    ["STR_ID_InnerPowerNpc[18786][Text2490]"] = "@STR_COMMON[483]",
    ["STR_ID_InnerPowerNpc[18786][Text2491]"] = "@STR_COMMON[595]",
    ["STR_ID_InnerPowerNpc[18786][Text2492]"] = "Sorry, you have Guild!.",
    ["STR_ID_InnerPowerNpc[18786][Text2493]"] = "You do not have 1000000 silvers with you.",
    ["STR_ID_InnerPowerNpc[18786][Text2494]"] = "Sorry! you need level 90 to use my options",
    ["STR_ID_InnerPowerNpc[18786][Text2495]"] = "Soory,the name is used!",
    ["STR_ID_InnerPowerNpc[18786][Text2496]"] = "Fate can bring lovers together. I hope you all can get married and live happily with your lovers. What can I do for you?",
    ["STR_ID_InnerPowerNpc[18786][Text2497]"] = "Sorry , but you're claimed today double Xp!",
    ["STR_ID_InnerPowerNpc[18786][Text2498]"] = "Sorry , you not have Blessing!",
    ["STR_ID_InnerPowerNpc[18786][Text2499]"] = "if you marriage left you nothing but regret and pain, then bring 3 Meteors,i can help you out.",
    ["STR_ID_InnerPowerNpc[18786][Text2500]"] = "You don`t have a wife",
    ["STR_ID_InnerPowerNpc[18786][Text2501]"] = "You don`t have 3 Meteors",
    ["STR_ID_InnerPowerNpc[18786][Text2502]"] = "Fate can bring lovers together. And everybody can live happily ever after... Ahhhh... What can I do for you?",
    ["STR_ID_InnerPowerNpc[18786][Text2503]"] = "Marriage~is~the~promise~forever.~Are~you~sure~that~you~want~to~spend~the~rest~of~your~life~with~your~lover?",
    ["STR_ID_InnerPowerNpc[18786][Text2504]"] = "Are~you~ready~to~propose?",
    ["STR_ID_InnerPowerNpc[18786][Text2505]"] = "Please click on your lover to propose.",
    ["STR_ID_InnerPowerNpc[18786][Text2506]"] = "@STR_COMMON[599]",
    ["STR_ID_InnerPowerNpc[18786][Text2507]"] = "@STR_COMMON[600]",
    ["STR_ID_InnerPowerNpc[18786][Text2508]"] = "@STR_COMMON[601]",
    ["STR_ID_InnerPowerNpc[18786][Text2509]"] = "Ahh, Warehouseman asked you here, huh? Yeah, you are in the right place! You know, weapons are the most important things in battle. Even the toughest warriors can`t survive without a weapon in their hands!",
    ["STR_ID_InnerPowerNpc[18786][Text2510]"] = "@STR_COMMON[9]",
    ["STR_ID_InnerPowerNpc[18786][Text2511]"] = "@STR_COMMON[9]",
    ["STR_ID_InnerPowerNpc[18786][Text2512]"] = "Most weapons and equipments are upgrade, you can buy them here.",
    ["STR_ID_InnerPowerNpc[18786][Text2513]"] = "@STR_COMMON[6]",
    ["STR_ID_InnerPowerNpc[18786][Text2514]"] = "@STR_COMMON[7]",
    ["STR_ID_InnerPowerNpc[18786][Text2515]"] = "@STR_COMMON[9]",
    ["STR_ID_InnerPowerNpc[18786][Text2516]"] = "@STR_COMMON[4]",
    ["STR_ID_InnerPowerNpc[18786][Text2517]"] = "@STR_COMMON[4]",
    ["STR_ID_InnerPowerNpc[18786][Text2518]"] = "@STR_COMMON[5]",
    ["STR_ID_InnerPowerNpc[18786][Text2519]"] = "The Barber! She is a talented hairdresser. She is worth paying a visit to! Go! ~Now, you should pay a visit to the Barber. I`m sure you will get something from her. ",
    ["STR_ID_InnerPowerNpc[18786][Text2520]"] = "Oops, I have told you all I know. You should pay a visit to the Barber. I`m sure you will get something from her.",
    ["STR_ID_InnerPowerNpc[18786][Text2521]"] = "Besides MP and HP potions, I also have a special item called Scroll, which will take you to whatever city it is made for! ~You are lucky! I have just got something new for you!",
    ["STR_ID_InnerPowerNpc[18786][Text2522]"] = "@STR_COMMON[5]",
    ["STR_ID_InnerPowerNpc[18786][Text2523]"] = "Please make 5 more spaces in your inventory",
    ["STR_ID_InnerPowerNpc[18786][Text2524]"] = "I am here selling all kinds of Accessories and Boots. You should not miss the equipment in my shop. ",
    ["STR_ID_InnerPowerNpc[18786][Text2525]"] = "Ah ha? Why don`t you just leave here? Let me guess...You want to buy something? ",
    ["STR_ID_InnerPowerNpc[18786][Text2526]"] = "@STR_COMMON[1]",
    ["STR_ID_InnerPowerNpc[18786][Text2527]"] = "Have you spoken with the Pharmacist? She has all kinds of potions that will be helpful to you in your journey.",
    ["STR_ID_InnerPowerNpc[18786][Text2528]"] = "I have boots, necklaces and rings, which are quite necessary to improve your skills and prowess ",
    ["STR_ID_InnerPowerNpc[18786][Text2529]"] = "@STR_COMMON[2]",
    ["STR_ID_InnerPowerNpc[18786][Text2530]"] = "@STR_COMMON[1]",
    ["STR_ID_InnerPowerNpc[18786][Text2531]"] = "@STR_COMMON[3]",
    ["STR_ID_InnerPowerNpc[18786][Text2532]"] = "I have told you all I know. I suggest you to find the Pharmacist. She should have something for you there.",
    ["STR_ID_InnerPowerNpc[18786][Text2533]"] = "I`m selling Headgears and Armors. They are so wonderful. You should not miss them. ",
    ["STR_ID_InnerPowerNpc[18786][Text2534]"] = "Why are you still here? Pay a visit to that lady!",
    ["STR_ID_InnerPowerNpc[18786][Text2535]"] = "@STR_COMMON[6]",
    ["STR_ID_InnerPowerNpc[18786][Text2536]"] = "The Storekeeper. She has many useful items. She is worth paying a visit to!",
    ["STR_ID_InnerPowerNpc[18786][Text2537]"] = "I have Armors and Headgears of all classes! Different classes use different kinds of equipment. Right click the equipment in my shop to buy it! ",
    ["STR_ID_InnerPowerNpc[18786][Text2538]"] = "@STR_COMMON[2]",
    ["STR_ID_InnerPowerNpc[18786][Text2539]"] = "@STR_COMMON[6]",
    ["STR_ID_InnerPowerNpc[18786][Text2540]"] = "@STR_COMMON[7]",
    ["STR_ID_InnerPowerNpc[18786][Text2541]"] = "@STR_COMMON[8]",
    ["STR_ID_InnerPowerNpc[18786][Text2542]"] = "@STR_COMMON[8]",
    ["STR_ID_InnerPowerNpc[18786][Text2543]"] = "@STR_COMMON[686]",
    ["STR_ID_InnerPowerNpc[18786][Text2544]"] = "@STR_COMMON[687]",
    ["STR_ID_InnerPowerNpc[18786][Text2545]"] = "@STR_COMMON[686]",
    ["STR_ID_InnerPowerNpc[18786][Text2546]"] = "My hero, you`re chosen by God of Dragon as the new generation for the mythical power.",
    ["STR_ID_InnerPowerNpc[18786][Text2547]"] = "Good! Now, I`m transferring my Power of Dragon to you. Feel it, and remember that Dragon`s ",
    ["STR_ID_InnerPowerNpc[18786][Text2548]"] = "@STR_COMMON[687]",
    ["STR_ID_InnerPowerNpc[18786][Text2549]"] = "There are many things for you to learn in this world! Um, I guess you want to learn more, huh? ",
    ["STR_ID_InnerPowerNpc[18786][Text2550]"] = "@STR_COMMON[746]",
    ["STR_ID_InnerPowerNpc[18786][Text2551]"] = "@STR_COMMON[746]",
    ["STR_ID_InnerPowerNpc[18786][Text2552]"] = "Here Level 140 Free.",
    ["STR_ID_InnerPowerNpc[18786][Text2553]"] = "@STR_COMMON[707]",
    ["STR_ID_InnerPowerNpc[18786][Text2554]"] = "@STR_COMMON[350]",
    ["STR_ID_InnerPowerNpc[18786][Text2555]"] = "I started learning KungFu where i was very young.Now, i have learn to master my chi very well! Wanna have a try? .",
    ["STR_ID_InnerPowerNpc[18786][Text2556]"] = "@STR_COMMON[351]",
    ["STR_ID_InnerPowerNpc[18786][Text2557]"] = "@STR_COMMON[350]",
    ["STR_ID_InnerPowerNpc[18786][Text2558]"] = "Oh, a message from the Recruit Master ? I see. He wana me to teach you how to master you Chi.",
    ["STR_ID_InnerPowerNpc[18786][Text2559]"] = "Good job! That is what i want you to do! Ok! Hope this kill will help you in the future.",
    ["STR_ID_InnerPowerNpc[18786][Text2560]"] = "@STR_COMMON[351]",
    ["STR_ID_InnerPowerNpc[18786][Text2561]"] = "General Zhao in Twin City will tel you more about the team system! Go speak with him !",
